import type { AdvancedQuestion, AdvancedStep } from "../advanced-lessons";

// sqr rota las opciones según `shift` para que la respuesta correcta no quede
// siempre en el mismo índice (evita el patrón "la correcta siempre es A").
// Mismo patrón que app/lessons-extra-parts/m01.ts.
const sqr = (prompt: string, correct: string, wrong: [string, string, string], shift: number, why: string, code = ""): AdvancedQuestion => {
  const all = [correct, ...wrong];
  const options = all.map((_, k) => all[(k + shift) % 4]);
  const answer = (4 - shift) % 4;
  return { prompt, options, answer, why, code };
};

export const stepsN03N05: AdvancedStep[] = [
 {id:"n03-http-rest",title:"HTTP y REST",
  summary:"REST es un estilo arquitectónico sobre HTTP que modela recursos con URIs y los manipula con verbos estándar (GET, POST, PUT, PATCH, DELETE). Es stateless: cada request debe traer toda la información necesaria, sin depender de sesión guardada en el servidor entre llamadas. La idempotencia (repetir la operación produce el mismo efecto) es clave en GET, PUT y DELETE; POST típicamente no es idempotente porque cada llamada puede crear un recurso nuevo.",
  code:"GET    /api/books/5      -> obtiene el libro 5\nPOST   /api/books        -> crea un libro nuevo (no idempotente)\nPUT    /api/books/5      -> reemplaza el libro 5 (idempotente)\nPATCH  /api/books/5      -> actualiza parcialmente el libro 5\nDELETE /api/books/5      -> elimina el libro 5 (idempotente)",
  questions:[
   sqr("¿Cuál verbo HTTP típico NO es idempotente (repetirlo puede crear varios recursos distintos cada vez)?","POST",["GET","PUT","DELETE"],0,"Cada POST puede crear un nuevo recurso; repetir la misma petición POST varias veces produce efectos distintos (varios recursos), a diferencia de GET, PUT o DELETE."),
   sqr("¿Qué significa que REST sea 'stateless'?","Cada request debe incluir toda la información necesaria; el servidor no guarda sesión del cliente entre llamadas",["El servidor nunca guarda datos en una base de datos","El cliente no puede enviar headers de autenticación","Cada respuesta debe estar vacía"],1,"Stateless significa que el servidor no mantiene contexto de conversación entre peticiones; cada request se procesa de forma independiente y autocontenida."),
   sqr("Si se llama DELETE /api/books/5 dos veces seguidas, ¿sigue siendo idempotente aunque la segunda llamada responda 404?","Sí: aunque la segunda llamada responda 404, el estado final (recurso ausente) es el mismo, así que DELETE sigue siendo idempotente",["No, porque la segunda respuesta ya no es 200/204","No, DELETE nunca es idempotente","Sí, pero solo si se usa PATCH en su lugar"],2,"La idempotencia se define por el efecto en el servidor, no por el código de respuesta: en ambos casos el libro 5 termina no existiendo.","DELETE /api/books/5  -> 204 No Content\nDELETE /api/books/5  -> 404 Not Found (ya no existía)"),
   sqr("¿Qué significa 'idempotente' en el contexto de HTTP?","Ejecutar la misma operación una o varias veces produce el mismo efecto en el servidor",["La operación siempre devuelve el mismo cuerpo JSON","La operación se ejecuta más rápido cada vez que se repite","La operación nunca puede fallar"],3,"Idempotencia es una garantía sobre el efecto final en el servidor tras repetir la operación, no sobre el contenido exacto de la respuesta ni el rendimiento."),
   sqr("¿Cuál es la diferencia principal entre PUT y PATCH?","PUT reemplaza el recurso completo; PATCH aplica una modificación parcial",["PUT es solo para crear; PATCH es solo para leer","PATCH es idempotente y PUT no lo es","No hay diferencia semántica, son sinónimos"],0,"PUT envía la representación completa del recurso (reemplazo); PATCH envía solo los cambios a aplicar sobre el recurso existente."),
   sqr("¿Cuál URI sigue mejor las convenciones REST para obtener el pedido 42?","GET /api/orders/42",["GET /api/getOrder?id=42","POST /api/Order_Get/42","GET /api/orders/action/get/42"],1,"REST nomina recursos con sustantivos en plural (/orders) y usa el verbo HTTP (GET) para expresar la acción, en vez de codificar el verbo en la URL."),
   sqr("¿Por qué GET no debería tener efectos secundarios (como modificar datos)?","Porque clientes, proxies y navegadores pueden repetir, cachear o precargar peticiones GET asumiendo que son seguras",["Porque GET no permite enviar parámetros","Porque el servidor rechaza cualquier GET con query string","Porque HTTP/1.1 prohíbe técnicamente los GET con esa función"],2,"GET se considera una operación 'segura' (safe): la infraestructura HTTP (caché, prefetch, reintentos) asume que no cambia el estado del servidor."),
   sqr("Si se envía dos veces el mismo PUT con idéntico payload, ¿es idempotente aunque escriba datos?","Sí, porque enviar el mismo PUT varias veces deja el recurso en el mismo estado final",["No, cualquier operación de escritura es no idempotente por definición","Solo es idempotente si el servidor cachea la respuesta","No, PUT se comporta igual que POST"],3,"Idempotencia no significa 'sin efectos', significa que repetir la operación no cambia el resultado final más allá de la primera vez."),
   sqr("¿Qué diferencia hay entre un estilo REST y un estilo RPC para diseñar una API?","REST modela recursos y usa verbos HTTP estándar sobre ellos; RPC expone acciones con nombres propios como endpoints (por ejemplo /createOrder)",["Son exactamente el mismo estilo con distinto nombre","RPC siempre usa JSON y REST nunca","REST no puede usarse sobre HTTPS"],0,"RPC modela funciones/acciones remotas; REST modela recursos direccionables por URI manipulados con verbos HTTP genéricos."),
   sqr("¿Es correcto decir que HTTP y REST son sinónimos?","No: HTTP es el protocolo de transporte; REST es un estilo arquitectónico que comúnmente se implementa sobre HTTP",["Sí, son intercambiables","REST es una versión anterior de HTTP","HTTP solo existe para implementar APIs REST"],1,"HTTP es el protocolo; REST es un conjunto de principios de diseño (recursos, verbos, statelessness) que puede aplicarse usando HTTP, pero son conceptos distintos."),
  ]},
 {id:"n03-status-codes",title:"Endpoints y status codes",
  summary:"Los códigos de estado comunican el resultado de la operación: 2xx éxito, 4xx error del cliente, 5xx error del servidor. La trampa de entrevista más común es 401 vs 403: 401 Unauthorized significa que el cliente NO está autenticado; 403 Forbidden significa que sí está autenticado pero no tiene permiso para esa acción. En ASP.NET Core, [ApiController] devuelve automáticamente 400 (no 422) cuando falla la validación del modelo.",
  code:"app.MapGet(\"/api/books/{id}\", (int id, BookDb db) =>\n{\n    var book = db.Books.Find(id);\n    return book is null ? Results.NotFound() : Results.Ok(book);\n});",
  questions:[
   sqr("Un POST que crea un recurso nuevo exitosamente, ¿qué código debería devolver idealmente?","201 Created, idealmente con un header Location apuntando al nuevo recurso",["200 OK sin más información","204 No Content","202 Accepted siempre"],0,"201 Created indica explícitamente que se creó un recurso nuevo; el header Location facilita al cliente obtenerlo."),
   sqr("Un DELETE exitoso que no devuelve cuerpo, ¿qué código es más apropiado?","204 No Content",["200 OK con el recurso eliminado en el body","201 Created","202 Accepted"],1,"204 indica éxito sin contenido en la respuesta, apropiado cuando no hay nada que devolver tras eliminar."),
   sqr("¿Cuál es la diferencia entre 401 Unauthorized y 403 Forbidden?","401 significa que el cliente no está autenticado (o sus credenciales son inválidas); 403 significa que está autenticado pero no tiene permiso para esa acción",["401 y 403 son sinónimos intercambiables","401 es para errores del servidor y 403 para errores del cliente","403 se usa cuando el token expiró y 401 cuando el rol es insuficiente"],2,"Pese a su nombre confuso, 401 es sobre identidad (autenticación) y 403 es sobre permisos (autorización) ya conocida la identidad."),
   sqr("¿Cuándo es apropiado devolver 400 Bad Request?","Cuando el servidor no puede procesar la petición porque su sintaxis o estructura es inválida (por ejemplo JSON malformado o tipos incorrectos)",["Cuando el recurso solicitado no existe","Cuando el usuario no tiene permisos suficientes","Cuando hubo una excepción no controlada en el servidor"],3,"400 indica un problema con la petición en sí (formato/sintaxis inválida), distinto de 404 (recurso ausente), 403 (permisos) o 500 (fallo del servidor)."),
   sqr("Con [ApiController], si falla la validación de un DTO (por ejemplo falta un campo [Required]), ¿qué código devuelve ASP.NET Core por defecto?","400 Bad Request con un ValidationProblemDetails generado automáticamente por el filtro de validación",["422 Unprocessable Entity siempre por defecto","200 OK con una lista de errores en el body","500 Internal Server Error"],0,"El filtro automático de [ApiController] intercepta ModelState inválido y responde 400 con ValidationProblemDetails antes de ejecutar la acción; no usa 422 por defecto."),
   sqr("GET /api/books/999 y el libro 999 no existe. ¿Qué código corresponde?","404 Not Found",["400 Bad Request","410 Gone siempre","204 No Content"],1,"404 indica que el recurso identificado por esa URI no existe; 400 sería para una petición malformada, no para un ID inexistente pero válido."),
   sqr("¿En qué escenario es apropiado devolver 409 Conflict?","Al intentar crear un recurso que ya existe (clave duplicada) o al detectar un conflicto de concurrencia optimista",["Cuando el cliente no envía el header Content-Type","Cuando el servidor está temporalmente caído","Cuando la petición tarda demasiado en responder"],2,"409 comunica que la petición es válida pero entra en conflicto con el estado actual del recurso, típico en duplicados o ediciones concurrentes."),
   sqr("GET /api/books?category=unknown no encuentra ningún libro. ¿Qué debería devolver el endpoint?","200 OK con un array vacío en el body",["404 Not Found porque no hay elementos","204 No Content obligatoriamente","400 Bad Request"],3,"Una colección vacía sigue siendo una respuesta exitosa a 'listar recursos que cumplen el filtro'; 404 se reserva para un recurso individual inexistente."),
   sqr("¿Cuándo corresponde devolver 500 Internal Server Error?","Ante una excepción no controlada u otro fallo inesperado del servidor al procesar una petición por lo demás válida",["Cuando el cliente envía un JSON inválido","Cuando el usuario no está autenticado","Cuando el recurso solicitado no existe"],0,"500 comunica que el problema está del lado del servidor (bug, dependencia caída, etc.), no un error atribuible a la petición del cliente."),
   sqr("En el código de ejemplo, ¿qué código de estado devuelve el endpoint cuando el libro no existe?","404",["200","400","204"],1,"book is null hace que se ejecute Results.NotFound(), que produce un 404.","app.MapGet(\"/api/books/{id}\", (int id, BookDb db) =>\n{\n    var book = db.Books.Find(id);\n    return book is null ? Results.NotFound() : Results.Ok(book);\n});"),
  ]},
 {id:"n03-dtos-validation",title:"DTOs y validación",
  summary:"Un DTO (Data Transfer Object) es un tipo dedicado a exponer o recibir datos por la API, distinto de la entidad de dominio/EF Core. Exponer entidades EF directamente arriesga sobre-exposición de datos, over-posting (mass assignment) y acopla el contrato público al esquema de la base de datos. Data Annotations ([Required], [StringLength], [Range], [EmailAddress]) o FluentValidation validan la forma de la entrada antes de tocar el dominio; las reglas que dependen del estado de la base de datos (como unicidad) requieren una verificación adicional en el servicio.",
  code:"public record CreateBookDto(\n    [property: Required, StringLength(200)] string Title,\n    [property: Range(1, 5000)] int Pages);\n\npublic class Book // entidad EF, no se expone directamente\n{\n    public int Id { get; set; }\n    public string Title { get; set; } = \"\";\n    public int Pages { get; set; }\n    public Author Author { get; set; } = null!;\n}",
  questions:[
   sqr("¿Por qué se recomienda no exponer directamente las entidades de EF Core en los endpoints?","Porque expone columnas internas o sensibles, permite over-posting (mass assignment) y acopla el contrato público al esquema de la base de datos",["Porque EF Core no permite serializar sus entidades a JSON","Porque las entidades de EF Core no pueden tener propiedades públicas","Porque ASP.NET Core lo bloquea automáticamente en tiempo de compilación"],0,"Un DTO separa el contrato público de la API del modelo interno de persistencia, evitando fugas de datos y acoplamiento innecesario."),
   sqr("¿Qué es 'over-posting' (mass assignment)?","Un cliente envía en el body campos adicionales (como IsAdmin o Id) que terminan asignándose a propiedades que no debían ser modificables desde fuera",["Un ataque que satura el servidor con demasiadas peticiones POST","Un error de sintaxis en el JSON enviado","Enviar un archivo demasiado grande en el body"],1,"Si el binding asigna directamente a la entidad completa, un atacante puede intentar sobrescribir propiedades sensibles enviándolas en el body; un DTO limita qué campos son aceptables."),
   sqr("Con [ApiController], si CreateBookDto llega sin Title (marcado [Required]), ¿qué ocurre antes de ejecutar la acción?","El filtro de validación automática detecta el ModelState inválido y responde 400 sin llegar a ejecutar el cuerpo de la acción",["La acción se ejecuta y debe validar manualmente ModelState.IsValid","Se lanza una NullReferenceException no controlada","Se ejecuta la acción con Title en null sin advertencia"],2,"El filtro automático de [ApiController] corta el pipeline y devuelve 400 con los detalles de validación cuando el modelo no cumple las Data Annotations."),
   sqr("¿Qué valida [Range(1, 5000)] sobre la propiedad Pages?","Que el valor numérico enviado esté entre 1 y 5000 inclusive",["Que Pages tenga exactamente 5000 caracteres","Que Pages sea un string con longitud entre 1 y 5000","Que existan entre 1 y 5000 libros en la base de datos"],3,"[Range] restringe el valor numérico permitido de una propiedad, no su longitud como texto ni ninguna regla de la base de datos."),
   sqr("¿Qué diferencia hay entre usar Data Annotations y FluentValidation?","FluentValidation separa las reglas en clases dedicadas con una API fluida, útil para validaciones complejas o condicionales; Data Annotations son atributos declarados directamente sobre las propiedades del DTO",["Son mutuamente excluyentes y no pueden coexistir en el mismo proyecto","FluentValidation solo funciona en aplicaciones Blazor","Data Annotations valida en tiempo de compilación; FluentValidation solo en runtime"],0,"Ambas validan en runtime; la diferencia es de organización y expresividad: FluentValidation facilita reglas condicionales o compartidas entre DTOs."),
   sqr("¿Cuál es la forma correcta de convertir un CreateBookDto validado en la entidad Book que se persiste?","Un mapeo explícito (manual o con una librería como Mapster/AutoMapper) que asigne solo los campos permitidos",["Asignar directamente el DTO recibido como si fuera la entidad de EF (casteo implícito)","Serializar la entidad completa y devolverla tal cual al cliente","Ignorar el mapeo porque EF Core lo hace automáticamente sin configurarlo"],1,"El mapeo explícito evita que campos no deseados (o inexistentes en el DTO, como un rol) terminen sobrescribiendo la entidad de forma no controlada."),
   sqr("¿Para qué sirve el atributo [EmailAddress] en un DTO?","Validar que el valor de la propiedad tiene el formato general de una dirección de correo",["Enviar automáticamente un correo de confirmación al usuario","Cifrar el valor antes de guardarlo en la base de datos","Convertir el campo en la clave primaria del DTO"],2,"[EmailAddress] es una Data Annotation de formato: valida la forma del string, no ejecuta ningún efecto secundario como enviar correos."),
   sqr("¿Por qué es razonable usar un 'record' de C# para modelar un DTO de entrada?","Porque ofrece una sintaxis concisa e igualdad por valor, adecuada para un objeto que solo transporta datos inmutables de una petición",["Porque los record son la única forma de aplicar Data Annotations","Porque los record se serializan más rápido que cualquier clase","Porque los record no permiten atributos de validación"],3,"Los records reducen código repetitivo para modelos de datos; siguen soportando Data Annotations normalmente sobre sus parámetros posicionales."),
   sqr("¿Basta con Data Annotations en el DTO para garantizar que el título de un libro nuevo sea único en la base de datos?","No: reglas que dependen del estado de la base de datos (como unicidad) requieren una verificación adicional en el servicio/dominio, no solo atributos declarativos",["Sí, Data Annotations valida automáticamente contra la base de datos","No, esas reglas deben ir todas dentro de la entidad de EF Core","Sí, basta con marcar la propiedad como [Required]"],0,"Las Data Annotations validan la forma de los datos de entrada de forma aislada; comprobar contra el estado actual de la base de datos requiere una consulta explícita en la capa de aplicación."),
   sqr("¿Qué ventaja de mantenibilidad da tener DtoIn (CreateBookDto) y DtoOut (BookResponseDto) separados en vez de un único DTO para todo?","Cada dirección puede exponer y exigir campos distintos (por ejemplo Id no se envía al crear, pero sí se devuelve), sin acoplar entrada y salida al mismo contrato",["Reduce el número de clases en el proyecto siempre","Es obligatorio porque ASP.NET Core lo exige por convención","Hace innecesaria cualquier validación adicional"],1,"Separar DTOs de entrada y salida evita forzar restricciones de un lado sobre el otro y hace explícito qué datos viajan en cada dirección."),
  ]},
 {id:"n03-openapi",title:"Swagger / OpenAPI",
  summary:"OpenAPI es una especificación (JSON/YAML) que describe los endpoints, parámetros, esquemas de request/response y códigos de estado de una API. Swashbuckle/Swagger genera ese documento a partir del código y expone Swagger UI, una interfaz interactiva para explorarlo y probarlo. El documento describe el contrato; no valida ni protege nada en runtime por sí mismo, eso lo sigue haciendo el pipeline de ASP.NET Core.",
  code:"builder.Services.AddEndpointsApiExplorer();\nbuilder.Services.AddSwaggerGen();\n// ...\nif (app.Environment.IsDevelopment())\n{\n    app.UseSwagger();\n    app.UseSwaggerUI();\n}",
  questions:[
   sqr("¿Qué relación hay entre OpenAPI y Swagger UI?","OpenAPI es la especificación/documento que describe la API; Swagger UI es una interfaz web que renderiza ese documento para explorarlo y probarlo",["Son sinónimos exactos del mismo archivo","Swagger UI genera el runtime completo de la API automáticamente","OpenAPI reemplaza a ASP.NET Core como framework"],1,"OpenAPI es el formato del contrato (JSON/YAML); Swagger UI es solo una de las herramientas que consumen ese documento para mostrarlo interactivamente."),
   sqr("¿El hecho de generar un documento OpenAPI hace que ASP.NET Core valide automáticamente las peticiones según ese esquema?","No: el documento describe el contrato, pero la validación real ocurre en el pipeline de ASP.NET Core (Data Annotations, filtros, etc.), no por el simple hecho de documentarlo",["Sí, Swagger rechaza automáticamente peticiones inválidas antes de llegar al controlador","Sí, pero solo si se usa el atributo [Required] junto con AddSwaggerGen","No, porque OpenAPI reemplaza los status codes por defecto"],2,"Generar la documentación es descriptivo, no prescriptivo: no agrega validación real, solo describe lo que el código ya hace (o debería hacer)."),
   sqr("¿Para qué sirve AddEndpointsApiExplorer() en un proyecto con Minimal APIs?","Habilita que ApiExplorer descubra los endpoints de Minimal APIs para que Swashbuckle pueda generar su documento OpenAPI",["Agrega automáticamente autenticación JWT a todos los endpoints","Crea una base de datos de ejemplo para probar la API","Convierte los Minimal APIs en controladores MVC"],3,"En controladores MVC este descubrimiento viene incluido; en Minimal APIs hace falta registrar explícitamente el ApiExplorer para que el generador de OpenAPI los detecte."),
   sqr("¿Para qué sirve [ProducesResponseType(StatusCodes.Status404NotFound)] sobre una acción?","Documentar en el esquema OpenAPI que ese endpoint puede responder 404, para que el cliente generado o Swagger UI lo reflejen",["Forzar a que el endpoint siempre responda 404 en ese caso","Registrar automáticamente un middleware de manejo de errores","Deshabilitar el código 200 para esa acción"],0,"[ProducesResponseType] es metadata de documentación: describe las respuestas posibles, no cambia el comportamiento real del endpoint."),
   sqr("¿Es buena práctica dejar Swagger UI accesible públicamente en producción sin ninguna restricción?","Depende: muchas organizaciones lo restringen o deshabilitan en producción porque expone el contrato completo de la API a cualquiera",["Siempre debe estar activo en producción sin excepción","Nunca puede activarse fuera de Development, es una limitación técnica del framework","Swagger UI reemplaza la necesidad de autenticación en producción"],1,"No hay una restricción técnica que lo impida, pero exponer el contrato completo (rutas, esquemas, ejemplos) en producción es una decisión de seguridad que suele evitarse o protegerse."),
   sqr("¿En qué formatos se puede servir habitualmente el documento generado por AddSwaggerGen?","JSON (y opcionalmente YAML)",["Solo XML","Solo un binario propietario de Microsoft","Solo Markdown"],2,"OpenAPI se expresa típicamente como JSON, aunque la especificación también admite YAML; Swashbuckle sirve JSON por defecto."),
   sqr("¿Qué se necesita en el .csproj para que los comentarios XML (///) enriquezcan las descripciones del documento OpenAPI?","Habilitar <GenerateDocumentationFile>true</GenerateDocumentationFile> y configurar Swashbuckle para incluir ese archivo XML",["Nada adicional, se incluyen automáticamente sin configuración","Marcar cada clase con [XmlDocumentation]","Renombrar el proyecto a algo terminado en .Docs"],3,"Sin generar el archivo de documentación XML y sin indicárselo a SwaggerGen, los comentarios /// no aparecen en el esquema generado."),
   sqr("¿Para qué se usa típicamente una herramienta como NSwag o OpenAPI Generator junto con el documento OpenAPI de una API?","Para generar automáticamente un cliente HTTP tipado (en C#, TypeScript, etc.) a partir del contrato descrito",["Para ejecutar pruebas de carga sobre la API","Para migrar automáticamente la base de datos","Para reemplazar la necesidad de escribir controladores"],0,"El documento OpenAPI, al ser una descripción formal del contrato, permite generar clientes tipados de forma automática en distintos lenguajes."),
   sqr("¿Basta con agregar [ApiController] a un controlador para que aparezca documentado en Swagger UI?","No: además se necesitan los servicios y el middleware de Swagger registrados (AddSwaggerGen, UseSwagger, UseSwaggerUI)",["Sí, [ApiController] genera automáticamente todo el documento OpenAPI","Sí, pero solo si el controlador hereda de SwaggerControllerBase","No, hace falta reescribir el controlador como Minimal API"],1,"[ApiController] habilita comportamientos de API (validación automática, binding), pero la generación y exposición del documento OpenAPI requiere su propia configuración."),
   sqr("En Minimal APIs, ¿qué suele hacer falta agregar a un endpoint (comparado con un controlador) para que su documentación en OpenAPI quede completa?","Metadata explícita como .WithName(), .Produces<T>() o .WithSummary(), ya que Minimal APIs no infiere tanto automáticamente como los atributos de un controlador",["Nada, Minimal APIs siempre genera documentación idéntica a los controladores sin configuración extra","Convertir el endpoint en un controlador MVC","Quitar AddEndpointsApiExplorer()"],2,"Los controladores aprovechan atributos y convenciones MVC para enriquecer el esquema; en Minimal APIs suele ser necesario declarar explícitamente esa metadata en la cadena fluida del endpoint."),
  ]},
 {id:"n03-filters",title:"Filtros",
  summary:"Los filtros interceptan el pipeline de ejecución de una acción/endpoint (Authorization, Resource, Action, Exception y Result filters en MVC) para aplicar lógica transversal como logging, manejo de errores o validación sin repetirla en cada endpoint. Se distinguen del middleware porque tienen acceso al contexto MVC (argumentos de la acción, ModelState, resultado), no solo al HttpContext crudo. En Minimal APIs el equivalente es IEndpointFilter.",
  code:"public class LogActionFilter : IActionFilter\n{\n    public void OnActionExecuting(ActionExecutingContext context) { /* antes de la acción */ }\n    public void OnActionExecuted(ActionExecutedContext context) { /* después de la acción */ }\n}\n\nbuilder.Services.AddControllers(options => options.Filters.Add<LogActionFilter>());",
  questions:[
   sqr("¿Cuál tipo de filtro se ejecuta primero en el pipeline de MVC?","Los filtros de autorización (Authorization filters)",["Los filtros de acción (Action filters)","Los filtros de resultado (Result filters)","Los filtros de excepción (Exception filters)"],0,"El orden del pipeline es Authorization -> Resource -> (model binding) -> Action -> Exception -> Result; la autorización se evalúa primero para poder rechazar la petición cuanto antes."),
   sqr("¿Qué diferencia principal hay entre un filtro de MVC y un middleware?","El filtro tiene acceso al contexto específico de MVC (argumentos de la acción, ModelState, resultado); el middleware solo ve el HttpContext crudo y corre para toda petición, mapee o no a una acción",["Son exactamente lo mismo con distinto nombre","El middleware solo puede usarse en Minimal APIs","Los filtros se ejecutan antes que el routing siempre"],1,"Los filtros se insertan dentro del pipeline de MVC/Endpoints una vez resuelta la acción; el middleware opera a un nivel más general, antes de que se sepa qué acción se ejecutará."),
   sqr("¿Cuál es el propósito principal de un Exception Filter?","Capturar excepciones no controladas lanzadas durante la ejecución de la acción (u otros filtros) y convertirlas en una respuesta HTTP adecuada",["Validar el ModelState antes de ejecutar la acción","Registrar métricas de autorización","Modificar la ruta antes del routing"],2,"Los Exception Filters actúan como un manejador de errores centrado en el pipeline MVC, atrapando excepciones que ocurren dentro de ese pipeline."),
   sqr("En Minimal APIs, ¿qué interfaz cumple un rol equivalente a un Action Filter de MVC?","IEndpointFilter",["IActionResult","IApplicationBuilder","IHostedService"],3,"IEndpointFilter permite interceptar la invocación de un endpoint de Minimal API antes y después de ejecutarlo, de forma similar a un Action Filter."),
   sqr("¿Cómo se registra un filtro para que aplique globalmente a todos los controladores, como en el ejemplo?","Agregándolo a options.Filters dentro de AddControllers(options => options.Filters.Add<T>())",["Decorando Program.cs con [GlobalFilter]","Solo es posible aplicarlo controlador por controlador con atributos","Registrándolo como middleware con app.Use()"],0,"options.Filters.Add<T>() dentro de AddControllers registra el filtro para que se ejecute en cada acción de cada controlador, sin decorar cada uno individualmente."),
   sqr("¿En qué momento del pipeline se ejecuta OnActionExecuting respecto al model binding?","Después de que el model binding ya asignó los argumentos de la acción, pero antes de invocar el método de la acción",["Antes de que exista cualquier información de la ruta","Después de que la acción ya se ejecutó completamente","Al mismo tiempo que el middleware de autenticación"],1,"Para cuando corre un Action Filter, los parámetros ya fueron enlazados (y ya pueden inspeccionarse/modificarse) pero la acción todavía no se invoca."),
   sqr("Con [ApiController], si el ModelState resulta inválido, ¿el cuerpo de la acción llega a ejecutarse?","No: el filtro automático de validación de modelo corta el pipeline y devuelve 400 sin llegar a ejecutar el cuerpo de la acción",["Sí, la acción se ejecuta igual y debe revisar ModelState.IsValid manualmente","Sí, pero solo devuelve una advertencia en los logs","No, pero en su lugar se lanza una excepción no controlada"],2,"El filtro de validación automática de [ApiController] corta el pipeline apenas detecta ModelState inválido, antes de invocar la acción."),
   sqr("¿Qué tipo de filtro representa el atributo [Authorize] aplicado sobre un controlador o acción?","Un Authorization filter",["Un Result filter","Un Exception filter","Un Resource filter de solo lectura"],3,"[Authorize] se implementa mediante el mecanismo de Authorization filters del pipeline de MVC, que corre antes que cualquier otro tipo de filtro."),
   sqr("¿Para qué es especialmente útil un Resource filter frente a un Action filter?","Para cortocircuitar el pipeline muy temprano (por ejemplo servir una respuesta cacheada) incluso antes del model binding",["Para acceder al resultado final ya serializado","Para capturar excepciones lanzadas por la vista","Para registrar el usuario autenticado únicamente"],0,"Los Resource filters se ejecutan antes del model binding, por lo que pueden evitar trabajo costoso (como bindear o ejecutar la acción) devolviendo una respuesta directamente."),
   sqr("¿Qué atributos permiten aplicar un filtro a una sola acción en lugar de registrarlo globalmente?","[ServiceFilter(typeof(T))] o [TypeFilter(typeof(T))] sobre el controlador o la acción",["[GlobalOnly] sobre el método Main","Modificar app.UseRouting() con el nombre del filtro","No es posible, todos los filtros son siempre globales"],1,"[ServiceFilter] y [TypeFilter] permiten aplicar un filtro concreto de forma selectiva a un controlador o acción específicos, en vez de registrarlo para toda la aplicación."),
  ]},
 {id:"n03-versioning",title:"Versionado",
  summary:"Versionar una API permite evolucionar su contrato sin romper a los clientes existentes. Las estrategias más comunes son por segmento de URL (/api/v1/orders), por header personalizado (X-Api-Version) o por query string (?api-version=1); el paquete Asp.Versioning.Http implementa las tres mediante distintos ApiVersionReader, y ApiVersionReader.Combine() permite soportar varias a la vez durante una transición.",
  code:"builder.Services.AddApiVersioning(options =>\n{\n    options.DefaultApiVersion = new ApiVersion(1, 0);\n    options.AssumeDefaultVersionWhenUnspecified = true;\n    options.ApiVersionReader = new UrlSegmentApiVersionReader();\n});\n\n[ApiVersion(\"1.0\")]\n[Route(\"api/v{version:apiVersion}/orders\")]\npublic class OrdersController : ControllerBase { }",
  questions:[
   sqr("¿Cuál estrategia hace explícita la versión directamente en la ruta, sin depender de headers ni query string?","Versionado por segmento de URL (/api/v1/orders)",["Versionado por header personalizado (X-Api-Version)","Versionado por query string (?api-version=1)","Versionado por Media Type (Accept header)"],0,"UrlSegmentApiVersionReader lee la versión desde un segmento propio de la ruta, como v1 en /api/v1/orders."),
   sqr("¿Qué ventaja práctica tiene el versionado por segmento de URL frente al versionado por header?","Es visible y fácil de probar en cualquier cliente HTTP o navegador, y queda inequívoco en logs y analítica",["Es la única estrategia que soporta HTTPS","Es la única forma de versionar soportada por ASP.NET Core","No requiere declarar ningún ApiVersion en el controlador"],1,"Al estar en la URL, la versión es visible sin inspeccionar headers, lo que simplifica pruebas manuales, documentación y análisis de tráfico."),
   sqr("¿Cuál es la principal desventaja del versionado por header personalizado (X-Api-Version)?","La versión queda invisible en la URL; hay que inspeccionar los headers para saber qué versión se está usando, dificultando pruebas rápidas en un navegador",["No puede combinarse nunca con autenticación","Obliga a duplicar toda la lógica de negocio por versión","Es la única estrategia prohibida por el estándar HTTP"],2,"Al no aparecer en la URL, probar o depurar la versión usada requiere herramientas que permitan inspeccionar/editar headers, a diferencia de simplemente cambiar la URL."),
   sqr("¿Qué logran DefaultApiVersion y AssumeDefaultVersionWhenUnspecified en la configuración?","Que las peticiones que no especifiquen ninguna versión se traten como si pidieran la versión por defecto configurada, en vez de fallar",["Que todas las versiones antiguas dejen de funcionar automáticamente","Que se genere una nueva versión automáticamente en cada deploy","Que el versionado quede deshabilitado por completo"],3,"Sin esta configuración, una petición sin versión explícita normalmente fallaría; con ella, se asume la versión por defecto declarada."),
   sqr("¿Es obligatorio que toda API REST incluya versionado en la URL para considerarse 'RESTful'?","No: el versionado es una decisión de diseño independiente, y existen varias estrategias válidas (URL, header, query string, media type) además de no versionar en absoluto para APIs internas simples",["Sí, REST exige explícitamente versionar por URL","Sí, de lo contrario la API no puede usar JSON","No, REST prohíbe cualquier forma de versionado"],0,"REST no dicta una estrategia de versionado específica; es una decisión práctica del equipo según sus necesidades de compatibilidad."),
   sqr("¿Para qué sirve ApiVersionReader.Combine() en Asp.Versioning.Http?","Para aceptar la versión desde múltiples fuentes a la vez (por ejemplo URL y header), útil durante una migración entre estrategias",["Para fusionar automáticamente dos versiones de la API en una sola","Para combinar varias bases de datos en una sola consulta","Para deshabilitar el versionado en ambientes de prueba"],1,"Combine() permite que el sistema de versionado intente leer la versión de más de un lugar (por ejemplo, primero la URL y si no está, el header), dando flexibilidad durante transiciones."),
   sqr("¿Qué representa el 'v1' en el segmento de ruta 'api/v{version:apiVersion}/orders'?","Un placeholder de ruta que ApiVersionReader resuelve como el número de versión solicitado, validado por la restricción de ruta 'apiVersion'",["Un literal fijo que nunca cambia entre despliegues","El nombre de la base de datos usada por ese controlador","Un alias del nombre del controlador OrdersController"],2,"{version:apiVersion} es un parámetro de ruta con la restricción especial 'apiVersion' que el sistema de versionado usa para extraer y validar la versión solicitada."),
   sqr("¿Qué implica, en términos de compatibilidad, subir la versión MAYOR de una API (de v1 a v2) frente a agregar un campo opcional nuevo?","Que se introducen cambios que rompen la compatibilidad con clientes existentes de v1, a diferencia de un cambio aditivo y opcional que normalmente no requiere una nueva versión mayor",["Son equivalentes; cualquier cambio siempre exige subir la versión mayor","Subir la versión mayor nunca afecta a los clientes existentes","Agregar un campo opcional siempre rompe a los clientes antiguos"],3,"Convencionalmente, los cambios incompatibles (romper un contrato existente) ameritan una nueva versión mayor; los cambios aditivos y opcionales pueden convivir dentro de la misma versión."),
   sqr("Además de URL, header y query string, ¿qué otra estrategia de versionado existe basada en el header Accept?","Versionado por Media Type (vendor-specific media types), donde el cliente indica la versión dentro del valor del header Accept",["Versionado por cookies de sesión","Versionado por el user-agent del navegador","Versionado por el idioma configurado en Accept-Language"],0,"El versionado por media type codifica la versión dentro del tipo de contenido solicitado en Accept, como application/vnd.miapi.v2+json."),
   sqr("¿Qué controla, en el ejemplo, que solo las peticiones a /api/v1/orders (y no a otra versión no declarada) lleguen a OrdersController?","El atributo [ApiVersion(\"1.0\")] combinado con la ruta versionada, que asocia ese controlador únicamente a la versión declarada",["Nada, cualquier valor de versión en la URL llega siempre a este controlador","El atributo [Route] por sí solo, sin relación con el versionado","La configuración de CORS del proyecto"],1,"[ApiVersion] declara explícitamente qué versión(es) atiende el controlador; el sistema de versionado usa eso junto con la ruta para enrutar correctamente según la versión solicitada."),
  ]},
 {id:"n03-rate-limiting",title:"Rate limiting",
  summary:"Desde .NET 7, Microsoft.AspNetCore.RateLimiting ofrece middleware de rate limiting integrado, sin depender de un paquete de terceros ni de Redis para una sola instancia. Los algoritmos disponibles son Fixed Window, Sliding Window, Token Bucket y Concurrency Limiter (este último limita peticiones simultáneas, no por periodo de tiempo). Por defecto, RejectionStatusCode es 503 Service Unavailable, no 429 Too Many Requests; hay que configurarlo explícitamente si se quiere seguir RFC 6585.",
  code:"builder.Services.AddRateLimiter(options =>\n{\n    options.RejectionStatusCode = StatusCodes.Status429TooManyRequests;\n    options.AddFixedWindowLimiter(\"fixed\", opt =>\n    {\n        opt.PermitLimit = 10;\n        opt.Window = TimeSpan.FromSeconds(10);\n        opt.QueueLimit = 0;\n    });\n});\napp.UseRateLimiter();\napp.MapGet(\"/api/data\", () => \"ok\").RequireRateLimiting(\"fixed\");",
  questions:[
   sqr("¿Qué método de extensión registra el middleware de rate limiting en el pipeline?","app.UseRateLimiter()",["app.UseThrottling()","app.MapRateLimiter()","app.UseCors() combinado con una opción RateLimit=true"],0,"UseRateLimiter() inserta el middleware que aplica las políticas de límite configuradas con AddRateLimiter() a las peticiones entrantes."),
   sqr("Si no se configura RejectionStatusCode explícitamente, ¿qué código de estado devuelve por defecto una petición rechazada por el rate limiter?","503 Service Unavailable",["429 Too Many Requests por defecto, sin configuración adicional","400 Bad Request","403 Forbidden"],1,"El valor por defecto de RejectionStatusCode es 503, no 429; hay que asignarlo explícitamente a Status429TooManyRequests para seguir la semántica de RFC 6585."),
   sqr("¿Cuál es la principal debilidad del algoritmo Fixed Window?","Un cliente puede enviar el límite completo de peticiones justo al final de una ventana y otro tanto al inicio de la siguiente, duplicando efectivamente el ráfaga permitida en poco tiempo",["No puede implementarse sin una base de datos externa","Nunca rechaza ninguna petición, solo las registra","Solo funciona con un único cliente a la vez"],2,"Al reiniciar el contador de golpe en cada ventana, una ráfaga alrededor del límite entre dos ventanas puede superar la tasa promedio pretendida."),
   sqr("¿Qué mejora aporta Sliding Window frente a Fixed Window?","Distribuye la evaluación de forma más continua sobre el período reciente en lugar de reiniciar todos los contadores de golpe, suavizando el problema de ráfagas en el borde de la ventana",["Elimina por completo la necesidad de un límite numérico","Permite peticiones ilimitadas durante las primeras 24 horas","Solo puede usarse junto con autenticación JWT"],3,"Sliding Window divide la ventana en segmentos y pondera la actividad reciente, evitando el salto abrupto de contador de Fixed Window."),
   sqr("¿Cómo funciona conceptualmente el algoritmo Token Bucket?","Un balde acumula tokens a una tasa fija; cada petición consume un token, y si no hay tokens disponibles la petición se rechaza o encola",["Cuenta peticiones por IP y las multiplica por un factor aleatorio","Bloquea a un cliente permanentemente tras la primera petición excedida","Solo limita el tamaño en bytes del body de la petición"],0,"Token Bucket permite ráfagas controladas mientras haya tokens acumulados, y limita la tasa sostenida por la velocidad de recarga del balde."),
   sqr("¿En qué se diferencia el Concurrency Limiter de los otros tres algoritmos (Fixed/Sliding Window, Token Bucket)?","Limita el número de peticiones simultáneas (en vuelo) en un momento dado, no la cantidad de peticiones por período de tiempo",["Es el único que puede combinarse con autenticación","Es el único que no puede configurarse por código","Limita únicamente el tamaño de la respuesta, no las peticiones"],1,"Los otros algoritmos controlan tasa a lo largo del tiempo; Concurrency Limiter controla cuántas operaciones concurrentes pueden estar en curso, útil para endpoints costosos."),
   sqr("En AddFixedWindowLimiter(\"fixed\", opt => {...}), ¿qué controla QueueLimit?","Cuántas peticiones que exceden el PermitLimit se ponen en cola a la espera de un cupo, en vez de rechazarse inmediatamente",["Cuántos clientes distintos pueden usar esa política a la vez","El tiempo máximo de vida del proceso del servidor","El número máximo de columnas devueltas por la API"],2,"QueueLimit define cuántas peticiones exceso se retienen esperando turno; con QueueLimit = 0 se rechazan inmediatamente sin encolar."),
   sqr("¿Qué logra encadenar .RequireRateLimiting(\"fixed\") a un endpoint concreto?","Aplica la política de rate limiting nombrada 'fixed' específicamente a ese endpoint (o grupo), en vez de a toda la aplicación",["Elimina cualquier límite de tasa para ese endpoint","Aplica autenticación obligatoria a ese endpoint","Convierte el endpoint en asíncrono automáticamente"],3,"RequireRateLimiting asocia una política previamente definida con AddFixedWindowLimiter (u otra) a endpoints o grupos concretos."),
   sqr("¿Qué diferencia hay entre un 'global limiter' y una política nombrada aplicada con RequireRateLimiting?","El global limiter se evalúa para toda petición que llegue a la aplicación, salvo excepciones explícitas; una política nombrada solo aplica a los endpoints que la referencian explícitamente",["Son exactamente lo mismo con distinto nombre en el código","El global limiter solo puede usar Token Bucket","Una política nombrada se aplica automáticamente a toda la app igual que el global limiter"],0,"GlobalLimiter se configura una vez y cubre todas las rutas por defecto; las políticas nombradas dan control fino por endpoint o grupo."),
   sqr("¿El rate limiting reemplaza la necesidad de autenticación y autorización en una API?","No: rate limiting protege la capacidad/disponibilidad del servicio frente a abuso de tráfico; es una preocupación distinta de verificar identidad (autenticación) y permisos (autorización)",["Sí, limitar la tasa de peticiones ya identifica y autoriza automáticamente al cliente","Sí, porque un cliente que supera el límite queda bloqueado permanentemente sin token","No tiene ninguna relación con la seguridad de la API"],1,"El rate limiting es una capa de protección contra abuso/sobrecarga; no verifica quién es el cliente ni qué puede hacer, eso lo resuelven authentication y authorization por separado."),
  ]},
 {id:"n03-challenge",title:"Reto API",
  summary:"Integra en un mismo diseño los conceptos del módulo: verbos y códigos correctos, DTOs que no exponen entidades, versionado explícito, autenticación/autorización coherente con 401 vs 403, y protección contra abuso con rate limiting. Un buen endpoint REST combina todas estas decisiones de forma consistente, no de forma aislada.",
  code:"[ApiController]\n[Authorize]\n[ApiVersion(\"1.0\")]\n[Route(\"api/v{version:apiVersion}/books\")]\npublic class BooksController : ControllerBase\n{\n    [HttpPost]\n    public IActionResult Create(CreateBookDto dto)\n    {\n        var book = new Book { Title = dto.Title };\n        _db.Books.Add(book);\n        _db.SaveChanges();\n        return CreatedAtAction(nameof(GetById), new { id = book.Id, version = \"1.0\" }, ToDto(book));\n    }\n\n    [HttpGet(\"{id}\")]\n    public IActionResult GetById(int id)\n    {\n        var book = _db.Books.Find(id);\n        return book is null ? NotFound() : Ok(ToDto(book));\n    }\n}",
  questions:[
   sqr("¿Qué código de estado devuelve CreatedAtAction en una creación exitosa?","201 Created, con un header Location apuntando a GetById",["200 OK sin header adicional","204 No Content","302 Found redirigiendo al recurso"],0,"CreatedAtAction genera un 201 y calcula automáticamente el header Location a partir de la acción y los valores de ruta indicados."),
   sqr("¿Por qué Create recibe un CreateBookDto en vez de la entidad Book directamente?","Para evitar over-posting y no acoplar el contrato público de la API al esquema interno de la entidad de EF Core",["Porque Book no puede deserializarse desde JSON","Porque los DTOs son obligatorios por el compilador de C#","Porque así se evita tener que llamar a SaveChanges()"],1,"Aceptar un DTO limita explícitamente qué campos puede enviar el cliente, evitando que sobrescriba propiedades no previstas de la entidad."),
   sqr("Si un cliente llama dos veces seguidas a POST /api/v1/books con el mismo payload, ¿qué ocurre?","Se crean dos libros distintos con IDs diferentes, porque POST no es idempotente",["Se crea un único libro, la segunda llamada es ignorada automáticamente","La segunda llamada devuelve 409 Conflict automáticamente","Ambas llamadas devuelven el mismo Id porque EF Core lo detecta como duplicado"],2,"Cada POST ejecuta Add + SaveChanges de forma independiente; nada en este código evita que se creen dos registros distintos con el mismo Title."),
   sqr("Si [Authorize] está presente y un cliente llama sin ningún token, ¿qué código debería recibir?","401 Unauthorized",["403 Forbidden","400 Bad Request","404 Not Found"],3,"Sin credenciales válidas, el cliente no está autenticado; ese es exactamente el caso que corresponde a 401, no a 403."),
   sqr("Si el cliente envía un token válido pero una política adicional exige el rol 'Editor' y no lo tiene, ¿qué código corresponde?","403 Forbidden",["401 Unauthorized","400 Bad Request","500 Internal Server Error"],0,"El cliente ya está autenticado (identidad válida); el problema es de permisos, lo que corresponde exactamente a 403."),
   sqr("¿Qué logra [ApiVersion(\"1.0\")] junto con la ruta 'api/v{version:apiVersion}/books'?","Que este controlador atienda específicamente la versión 1.0 de la API a través del segmento de URL, permitiendo evolucionar el contrato en versiones futuras sin romper a estos clientes",["Que la API ignore por completo el número de versión enviado","Que se genere automáticamente documentación Swagger","Que se aplique rate limiting automáticamente a esta ruta"],1,"El versionado explícito por URL asocia el controlador a una versión concreta, dejando espacio para introducir v2 con cambios incompatibles sin afectar a quienes siguen en v1."),
   sqr("Si se agrega .RequireRateLimiting(\"fixed\") a este grupo de endpoints, ¿qué problema mitiga?","El abuso de tráfico o sobrecarga del servicio por demasiadas peticiones en poco tiempo, sin relación con si el cliente está autorizado",["Los errores de validación del DTO","Los conflictos de concurrencia al guardar en la base de datos","La necesidad de versionar la API"],2,"El rate limiting protege la capacidad del servicio; es ortogonal a la autenticación, autorización o validación de datos."),
   sqr("¿Es necesario revisar ModelState.IsValid manualmente dentro de Create, dado que el controlador usa [ApiController]?","No: el filtro automático de validación de modelo ya intercepta un CreateBookDto inválido y responde 400 antes de ejecutar el cuerpo del método",["Sí, [ApiController] no incluye validación automática de ModelState","Sí, porque CreatedAtAction desactiva la validación automática","No, porque CreateBookDto no tiene ninguna Data Annotation"],0,"[ApiController] activa la validación automática de ModelState, por lo que revisarlo manualmente dentro del método sería redundante."),
   sqr("Si GetById no encuentra el libro solicitado, ¿qué devuelve el código mostrado?","404 Not Found, mediante NotFound()",["200 OK con un cuerpo vacío","400 Bad Request","500 Internal Server Error"],1,"book is null hace que se devuelva NotFound(), que produce un 404, coherente con la semántica de un recurso individual inexistente."),
   sqr("¿Cuál de las siguientes prácticas del ejemplo refleja mejor la 'higiene REST' enseñada en este módulo?","Usar DTOs de entrada/salida, códigos de estado específicos por caso (201/404), versionado explícito y separar autenticación (401) de autorización (403)",["Exponer directamente la entidad Book en cada respuesta para simplificar el código","Devolver siempre 200 OK sin importar el resultado de la operación","Ignorar la versión de la API porque todos los clientes usan la misma"],0,"El diseño combina coherentemente varios principios del módulo: contrato desacoplado (DTOs), semántica HTTP correcta, evolución controlada (versionado) y seguridad bien distinguida (401 vs 403)."),
  ]},
 {id:"n04-dbcontext",title:"DbContext y DbSet",
  summary:"DbContext representa una sesión con la base de datos: rastrea el estado de las entidades cargadas, traduce LINQ a SQL y coordina SaveChanges. DbSet<T> expone una colección consultable/mutable de una entidad. DbContext NO es thread-safe y debe tener vida corta; en ASP.NET Core, AddDbContext lo registra como Scoped por defecto, creando una instancia nueva por cada request/scope de inyección de dependencias.",
  code:"public class StoreContext : DbContext\n{\n    public StoreContext(DbContextOptions<StoreContext> options) : base(options) { }\n    public DbSet<Book> Books => Set<Book>();\n    public DbSet<Author> Authors => Set<Author>();\n}\n\n// Program.cs\nbuilder.Services.AddDbContext<StoreContext>(opt => opt.UseSqlServer(connectionString));",
  questions:[
   sqr("¿Con qué ciclo de vida (lifetime) registra AddDbContext<T> al DbContext en el contenedor de DI por defecto?","Scoped: se crea una instancia nueva por cada request/scope de inyección de dependencias",["Singleton: una única instancia para toda la aplicación","Transient: una instancia nueva cada vez que se inyecta, incluso dentro del mismo request","Static: no participa en inyección de dependencias"],0,"Scoped asegura que todos los servicios dentro del mismo request compartan la misma instancia de DbContext, pero cada request obtiene una instancia distinta."),
   sqr("¿Por qué no es seguro compartir la misma instancia de DbContext entre múltiples hilos concurrentes?","Porque DbContext no es thread-safe: usarlo simultáneamente desde varios hilos puede corromper su estado interno de tracking",["Porque consume demasiada memoria si se comparte entre hilos","Porque EF Core lo bloquea automáticamente con locks internos sin fallar","Porque solo permite una consulta por aplicación completa"],1,"EF Core documenta explícitamente que una instancia de DbContext no está diseñada para operaciones concurrentes desde múltiples hilos sobre el mismo contexto."),
   sqr("¿Qué representa DbSet<Book> dentro de StoreContext?","Una colección consultable (IQueryable) y mutable que mapea la entidad Book a su tabla correspondiente",["Una copia en memoria de toda la tabla Books cargada al iniciar la app","Un método estático que genera SQL manualmente","Una clase de configuración de logging"],2,"DbSet<T> es el punto de entrada para consultar (LINQ) y modificar (Add/Remove) instancias de una entidad concreta a través del contexto."),
   sqr("¿Qué problema puede causar registrar un DbContext como Singleton en una aplicación web?","Al vivir durante toda la aplicación, acumula estado de tracking sin límite y se comparte entre requests concurrentes, violando que no es thread-safe",["Ningún problema, es una optimización recomendada para reducir conexiones","Hace que las migraciones dejen de funcionar","Impide usar LINQ sobre los DbSet"],0,"Un DbContext Singleton mezclaría el estado de tracking de múltiples requests simultáneos sobre una instancia no diseñada para concurrencia, generando comportamiento impredecible."),
   sqr("¿Qué logra escribir 'public DbSet<Book> Books => Set<Book>();' en vez de un campo autoimplementado clásico?","Es una forma moderna equivalente de exponer el DbSet<Book>, resolviéndolo desde el modelo del contexto en cada acceso",["Desactiva el change tracking para esa entidad específicamente","Convierte a Book en una entidad de solo lectura","Obliga a usar AsNoTracking en cada consulta sobre Books"],1,"Set<T>() es el método de DbContext para obtener el DbSet de una entidad; esta sintaxis con expression-bodied member es equivalente a declarar la propiedad con { get; set; } inicializada en el constructor."),
   sqr("¿Qué hace SaveChanges() sobre un DbContext?","Persiste en la base de datos todos los cambios rastreados (inserts, updates, deletes) acumulados desde la última llamada, dentro de una transacción implícita",["Ejecuta inmediatamente cada Add() o Remove() apenas se llama, sin esperar una llamada explícita","Recarga todas las entidades desde la base de datos descartando cambios locales","Solo aplica cambios a la primera entidad modificada"],2,"Los métodos como Add/Remove/modificar propiedades solo cambian el estado en memoria (tracking); SaveChanges es quien genera y ejecuta el SQL correspondiente."),
   sqr("¿Para qué se sobrescribe OnModelCreating(ModelBuilder modelBuilder) en un DbContext?","Para configurar el modelo mediante Fluent API: relaciones, índices, restricciones y otras convenciones que no se infieren automáticamente",["Para abrir la conexión a la base de datos manualmente","Para ejecutar las migraciones pendientes automáticamente","Para definir los DbSet, en lugar de declararlos como propiedades"],0,"OnModelCreating es el punto de extensión estándar para refinar con Fluent API el modelo que EF Core construyó por convención."),
   sqr("¿Qué configura 'opt.UseSqlServer(connectionString)' dentro de AddDbContext?","El proveedor de base de datos (SQL Server) y la cadena de conexión que StoreContext usará para conectarse",["El nivel de aislamiento de todas las transacciones futuras","El tiempo de vida (lifetime) del propio DbContext en el contenedor DI","El esquema exacto de todas las tablas sin necesidad de migraciones"],3,"UseSqlServer configura el proveedor EF Core correspondiente y la cadena de conexión; el lifetime del contexto lo determina AddDbContext en sí, no esta llamada."),
   sqr("En una aplicación de consola de larga duración (no web), ¿cuál es el patrón recomendado para usar un DbContext?","Crear y descartar (using/Dispose) una instancia nueva de DbContext por cada unidad de trabajo, en lugar de mantener una única instancia viva durante toda la ejecución",["Crear una única instancia estática y reutilizarla indefinidamente durante toda la vida del proceso","Registrar el DbContext como Singleton igual que en una app web","Evitar Dispose() porque EF Core lo gestiona automáticamente sin necesidad de using"],0,"Fuera del modelo de request/scope de ASP.NET Core, sigue aplicando la regla de mantener el DbContext con vida corta; crear uno por unidad de trabajo evita acumulación de tracking y problemas de concurrencia."),
   sqr("¿Es seguro inyectar un DbContext (Scoped) directamente en el constructor de un servicio registrado como Singleton?","No: un servicio Singleton captura esa instancia de DbContext y la reutiliza para siempre, violando su ciclo de vida corto y su falta de thread-safety; hay que usar IDbContextFactory<T> o crear un scope manualmente",["Sí, ASP.NET Core lo resuelve automáticamente sin ningún problema","Sí, siempre que el servicio Singleton no use async/await","No, pero solo si el proyecto usa Minimal APIs en vez de controladores"],1,"Mezclar lifetimes de esta forma (captive dependency) es un error clásico: el contenedor de DI de ASP.NET Core incluso puede lanzar una excepción de validación de scopes en desarrollo al detectarlo."),
  ]},
 {id:"n04-migrations",title:"Migrations",
  summary:"Una migración es una clase generada que representa los cambios de esquema (métodos Up/Down) necesarios para llevar la base de datos de un estado al siguiente. 'dotnet ef migrations add <Nombre>' genera el archivo comparando el modelo actual contra el snapshot guardado; 'dotnet ef database update' la aplica realmente a la base de datos. EF Core NO aplica migraciones automáticamente en producción: se requiere invocar explícitamente algo como context.Database.Migrate().",
  code:"dotnet ef migrations add AddBookPriceColumn\ndotnet ef database update",
  questions:[
   sqr("¿Qué comando crea un nuevo archivo de migración a partir de los cambios detectados en el modelo?","dotnet ef migrations add <Nombre>",["dotnet ef database update <Nombre>","dotnet ef migrations apply <Nombre>","dotnet ef snapshot add <Nombre>"],0,"'migrations add' compara el modelo actual contra el snapshot guardado y genera una nueva clase de migración con los cambios detectados."),
   sqr("¿Qué comando aplica realmente las migraciones pendientes a la base de datos?","dotnet ef database update",["dotnet ef migrations add","dotnet ef migrations apply","dotnet ef database migrate"],1,"'database update' ejecuta contra la base de datos configurada las migraciones que aún no se han aplicado, en orden."),
   sqr("¿EF Core aplica automáticamente las migraciones pendientes cuando la aplicación arranca en producción, sin ningún código adicional?","No: se requiere invocar explícitamente algo como context.Database.Migrate() (u otro mecanismo) para que se apliquen en tiempo de ejecución",["Sí, siempre las aplica automáticamente al arrancar cualquier app","Sí, pero solo la primera vez que se despliega la aplicación","No, y tampoco pueden aplicarse mediante código, solo por CLI"],2,"Aplicar migraciones es una acción explícita; sin invocar Migrate() (u otro proceso de despliegue equivalente), la base de datos no cambia aunque el código del modelo sí haya cambiado."),
   sqr("¿Qué representan los métodos Up y Down dentro de una clase de migración generada?","Up aplica los cambios de esa migración; Down revierte esos mismos cambios, usado al hacer rollback a una migración anterior",["Up sube el proyecto a producción; Down lo detiene","Up crea la base de datos; Down la elimina por completo siempre","Ambos hacen lo mismo, están duplicados por seguridad"],1,"Down permite deshacer una migración específica (por ejemplo con 'dotnet ef database update <MigraciónAnterior>'), revirtiendo exactamente lo que Up aplicó."),
   sqr("¿Para qué sirve el archivo ModelSnapshot.cs generado junto a las migraciones?","Es la referencia que EF Core usa para comparar el modelo actual contra el último estado migrado y así calcular la próxima migración correctamente",["Es un respaldo (backup) de los datos de la base de datos","Contiene las credenciales de conexión de cada ambiente","Sirve solo como documentación y no lo usa el propio EF Core"],0,"El snapshot representa el estado del modelo tal como quedó tras la última migración; sin él, EF Core no podría calcular con precisión el diff para la siguiente migración."),
   sqr("¿Por qué muchos equipos evitan llamar automáticamente a context.Database.Migrate() en cada arranque de la app en producción?","Porque puede causar bloqueos o tiempo de inactividad con tablas grandes, y es riesgoso si varias instancias arrancan a la vez e intentan migrar simultáneamente",["Porque Migrate() no existe realmente en EF Core","Porque solo funciona en bases de datos en memoria","Porque revierte automáticamente todas las migraciones anteriores"],0,"Se suele preferir aplicar migraciones como un paso controlado y único del pipeline de despliegue, en lugar de dejar que cada instancia de la app las dispare de forma concurrente al iniciar."),
   sqr("¿Es seguro borrar manualmente el archivo .cs de una migración del disco para 'deshacerla'?","No de forma segura: hay que usar 'dotnet ef migrations remove' para que EF Core también revierta correctamente el ModelSnapshot",["Sí, borrar el archivo es la forma oficial y recomendada de eliminar una migración","Sí, siempre que también se borre la base de datos completa","No, las migraciones no pueden eliminarse nunca una vez creadas"],1,"'migrations remove' elimina la última migración (si no fue aplicada) y actualiza el snapshot de forma consistente; borrar el archivo a mano deja el snapshot desincronizado."),
   sqr("¿Qué situación de equipo es un punto de fricción típico con el archivo ModelSnapshot.cs?","Que dos desarrolladores agreguen migraciones distintas en paralelo y, al fusionar sus ramas, el snapshot quede en conflicto o desincronizado",["Que el snapshot se regenere automáticamente sin conflictos al hacer merge","Que el snapshot deje de ser necesario a partir de EF Core 8","Que el snapshot se almacene siempre en la propia base de datos"],3,"Como el snapshot es un archivo generado que representa un único estado lineal del modelo, migraciones concurrentes en ramas distintas suelen producir conflictos de merge que hay que resolver con cuidado."),
   sqr("¿Qué hace 'dotnet ef database update 0'?","Revierte todas las migraciones aplicadas, dejando la base de datos en el estado anterior a la primera migración, usando los métodos Down",["Aplica únicamente la migración número 0","Elimina la base de datos por completo, incluyendo el propio motor","Actualiza únicamente la primera fila de cada tabla"],0,"El identificador especial '0' representa el estado 'sin ninguna migración aplicada'; EF Core ejecuta los Down necesarios en orden inverso para llegar ahí."),
   sqr("¿Qué contiene realmente el archivo de una migración generada, SQL crudo o código C#?","Código C# que usa la API de MigrationBuilder (independiente del proveedor), que EF Core traduce al dialecto SQL correspondiente al aplicarla",["SQL crudo específico de SQL Server siempre, sin importar el proveedor configurado","Solo JSON describiendo el esquema, sin ninguna lógica ejecutable","Un script de PowerShell que se ejecuta directamente"],0,"Las migraciones se escriben con la API fluida de MigrationBuilder en C#; EF Core genera el SQL específico del proveedor configurado (SQL Server, PostgreSQL, etc.) al momento de aplicarlas."),
  ]},
 {id:"n04-relationships",title:"Relationships",
  summary:"EF Core infiere relaciones 1 a muchos por convención (propiedad de navegación + clave foránea) y permite configurarlas explícitamente con Fluent API (HasOne/WithMany/HasForeignKey). Por convención, una relación requerida (FK no anulable) usa DeleteBehavior.Cascade y una opcional usa ClientSetNull. Desde EF Core 5, las relaciones muchos a muchos pueden modelarse sin una entidad de unión explícita, salvo que esa tabla intermedia necesite columnas propias.",
  code:"public class Author\n{\n    public int Id { get; set; }\n    public string Name { get; set; } = \"\";\n    public List<Book> Books { get; } = new();\n}\npublic class Book\n{\n    public int Id { get; set; }\n    public string Title { get; set; } = \"\";\n    public int AuthorId { get; set; }\n    public Author Author { get; set; } = null!;\n}\n\nmodelBuilder.Entity<Book>()\n    .HasOne(b => b.Author)\n    .WithMany(a => a.Books)\n    .HasForeignKey(b => b.AuthorId);",
  questions:[
   sqr("¿Qué representa la propiedad AuthorId dentro de Book, por convención de EF Core?","La clave foránea (foreign key) hacia Author, descubierta por convención a partir del nombre de la propiedad de navegación más 'Id'",["Un campo calculado sin relación con Author","El identificador único de Book en lugar de Id","Una propiedad que EF Core ignora por defecto"],0,"EF Core reconoce por convención propiedades como <Navegación>Id (AuthorId junto a la navegación Author) como la clave foránea de la relación."),
   sqr("¿Para qué se usa explícitamente HasOne(...).WithMany(...).HasForeignKey(...) en Fluent API?","Para configurar de forma explícita una relación uno a muchos, necesario cuando la convención no puede inferirla correctamente o se quiere sobreescribirla",["Para eliminar la relación entre Book y Author","Para crear una tabla intermedia obligatoria entre ambas entidades","Para convertir la relación en muchos a muchos automáticamente"],1,"Aunque muchas relaciones 1-a-muchos se infieren solas, Fluent API permite (o exige) declararlas explícitamente cuando hay ambigüedad, múltiples FKs posibles o se quiere personalizar el comportamiento."),
   sqr("Desde EF Core 5, ¿qué se necesita como mínimo para modelar una relación muchos a muchos entre dos entidades?","Una lista de navegación en cada lado (por ejemplo List<Book> en Author y List<Author> en Book); EF Core crea la tabla de unión implícitamente sin necesitar una clase de unión explícita",["Una clase de entidad de unión explícita siempre, sin excepciones","Ninguna configuración, EF Core la detecta aunque no existan colecciones en ningún lado","Un procedimiento almacenado personalizado"],0,"A partir de EF Core 5, declarar colecciones de navegación en ambos extremos basta para que EF Core infiera y gestione una tabla de unión implícita."),
   sqr("¿Cuándo es necesario modelar explícitamente una entidad de unión para una relación muchos a muchos, en vez de dejar que EF Core la genere implícitamente?","Cuando la tabla de unión necesita columnas propias además de las dos claves foráneas (por ejemplo una fecha de asignación)",["Siempre, la tabla implícita de EF Core 5+ no existe realmente","Nunca, la entidad de unión explícita ya no es soportada desde EF Core 5","Solo si se usa SQLite como proveedor"],0,"Si el vínculo entre dos entidades necesita datos propios (payload), hace falta modelarlo como una entidad completa con dos relaciones 1-a-muchos en vez de una tabla de unión oculta."),
   sqr("Con la configuración por convención mostrada (relación requerida, AuthorId no anulable), ¿qué ocurre por defecto al eliminar un Author que tiene Books asociados?","Se eliminan en cascada: por convención, una relación requerida (FK no anulable) usa DeleteBehavior.Cascade",["No pasa nada con los libros relacionados por defecto","Se lanza una excepción impidiendo borrar al autor, siempre por defecto","El campo AuthorId se pone en null automáticamente en la base de datos"],1,"EF Core configura Cascade por defecto para relaciones requeridas: al no poder existir un Book sin Author válido, eliminar al Author elimina también sus Books."),
   sqr("¿Para qué sirve configurar explícitamente .OnDelete(DeleteBehavior.Restrict) en una relación?","Para impedir la eliminación del padre a nivel de base de datos mientras existan hijos relacionados, en vez de eliminarlos en cascada o poner la FK en null",["Para permitir borrar el padre y los hijos simultáneamente sin restricciones","Para hacer que la relación pase de opcional a requerida","Para desactivar por completo el change tracking de esa relación"],0,"Restrict hace que la base de datos rechace (lance error) el DELETE del padre si aún existen hijos que lo referencian, forzando a manejarlos explícitamente antes."),
   sqr("¿Por qué una relación uno a uno requiere típicamente configurar HasForeignKey<T>() de forma explícita, a diferencia de una uno a muchos?","Porque en una relación 1 a 1, EF Core no puede inferir por sí solo cuál de las dos entidades debe alojar la clave foránea (dependiente) y cuál es el principal",["Porque las relaciones 1 a 1 no están soportadas por EF Core","Porque HasForeignKey<T>() es opcional y nunca se necesita realmente","Porque las relaciones 1 a 1 siempre usan una tabla de unión como las muchos a muchos"],0,"A diferencia de 1-a-muchos (donde el lado 'muchos' es claramente el dependiente), en una relación 1-a-1 ambos lados son simétricos, así que hay que indicar explícitamente cuál lleva la FK."),
   sqr("¿Es obligatorio marcar las propiedades de navegación como 'virtual' para que EF Core (Core, no EF6) las reconozca y las use?","No: EF Core no requiere que las propiedades de navegación sean virtual para funcionar; virtual solo es necesario si se habilita lazy loading con proxies",["Sí, siempre deben ser virtual o EF Core lanza una excepción al iniciar","Sí, porque virtual habilita el change tracking de esa propiedad","No, EF Core prohíbe explícitamente usar virtual en propiedades de navegación"],0,"A diferencia de Entity Framework 6, EF Core no exige virtual para eager/explicit loading; solo el mecanismo opcional de lazy loading basado en proxies runtime lo necesita."),
   sqr("¿Qué es una 'shadow property' en el contexto de relaciones de EF Core?","Una propiedad (frecuentemente una clave foránea) que existe en el modelo y en la base de datos, pero no tiene una propiedad CLR correspondiente explícita en la clase C#",["Una propiedad que solo existe en memoria y nunca se persiste","Una propiedad marcada con [NotMapped] que EF Core ignora","Un alias visual que Visual Studio muestra pero que no existe en la base de datos"],1,"Cuando una relación se configura sin exponer explícitamente la FK como propiedad CLR, EF Core la modela igual internamente como una 'shadow property', gestionada solo a través del change tracker."),
   sqr("En una relación muchos a muchos implícita (sin entidad de unión explícita), ¿es habitual necesitar acceder directamente a la tabla intermedia generada?","No habitualmente: por defecto queda oculta y se gestiona solo a través de las colecciones de navegación en ambos lados, salvo que se configure explícitamente con UsingEntity para exponerla",["Sí, es obligatorio consultarla manualmente con SQL crudo en cada operación","Sí, EF Core no permite consultar la relación sin acceder a esa tabla directamente","No, esa tabla nunca se crea realmente en la base de datos"],0,"El propósito de la tabla implícita es abstraer ese detalle: normalmente basta con manipular las colecciones de navegación (Author.Books, Book.Authors) sin tocar la tabla intermedia directamente."),
  ]},
 {id:"n04-linq-entities",title:"LINQ to Entities",
  summary:"LINQ to Entities traduce expresiones LINQ sobre un IQueryable<T> respaldado por EF Core a sentencias SQL. La ejecución es diferida: la consulta no viaja a la base de datos hasta llamar a un método de materialización (ToList, First, Count, etc.). Desde EF Core 3.0, si una parte de la consulta no puede traducirse a SQL, EF Core lanza una excepción en lugar de evaluarla silenciosamente en el cliente (salvo en la proyección final de nivel superior, con advertencia).",
  code:"var titles = db.Books\n    .Where(b => b.Pages > 100)\n    .OrderBy(b => b.Title)\n    .Select(b => b.Title)\n    .ToList();",
  questions:[
   sqr("¿En qué momento se ejecuta realmente la consulta SQL de esta cadena LINQ?","Al llamar a ToList(), no antes: la consulta sobre IQueryable<T> tiene ejecución diferida (deferred execution)",["En el momento en que se escribe la expresión Where","Al declarar la variable db.Books","Inmediatamente al llamar a OrderBy, antes de Select"],0,"Where/OrderBy/Select solo van componiendo una árbol de expresión; ningún SQL se ejecuta hasta un método de materialización como ToList, First o Count."),
   sqr("¿Qué diferencia clave hay entre encadenar .Where() sobre db.Books.ToList() y sobre db.Books directamente?","db.Books.ToList().Where(...) trae TODAS las filas a memoria y filtra en el cliente; db.Books.Where(...).ToList() traduce el filtro a SQL y solo trae las filas que cumplen",["Ambas formas generan exactamente el mismo SQL y rendimiento","La primera es más eficiente porque cachea el resultado","La segunda nunca puede usar índices de la base de datos"],1,"Materializar (ToList) antes de filtrar rompe la composición de IQueryable y fuerza a traer toda la tabla, perdiendo la traducción a SQL del filtro."),
   sqr("Desde EF Core 3.0, si una parte del predicado de Where usa un método de C# que no puede traducirse a SQL, ¿qué ocurre por defecto?","EF Core lanza una excepción en tiempo de ejecución en lugar de evaluar esa parte silenciosamente en el cliente",["Se evalúa automáticamente en el cliente sin ningún aviso, como en versiones anteriores a EF Core 3.0","La consulta se ignora y devuelve una lista vacía","Se ejecuta igual, pero el resultado queda desordenado"],0,"EF Core 3.0 eliminó la evaluación silenciosa en cliente dentro de la mayor parte de la consulta (se permite, con advertencia, solo en la proyección final de nivel superior) para evitar traer datasets completos por error."),
   sqr("¿Para qué sirve Include(b => b.Author) en una consulta de EF Core?","Para cargar de forma anticipada (eager loading) la entidad relacionada Author junto con cada Book, en la misma consulta o en consultas adicionales controladas",["Para excluir la propiedad Author del resultado","Para ordenar los resultados alfabéticamente por el nombre del autor","Para forzar que la consulta se ejecute de forma síncrona"],0,"Include indica explícitamente qué relaciones cargar junto con la entidad principal, evitando tener que acceder a ellas por separado más adelante."),
   sqr("Si se consulta db.Books.ToList() sin Include(b => b.Author) y sin lazy loading configurado, ¿qué ocurre al acceder a book.Author.Name después?","Author probablemente sea null (no fue cargado), lo que provoca una NullReferenceException al intentar leer Name",["Author se carga automáticamente en ese momento sin configuración adicional","Se lanza un error de compilación","Author contiene siempre un objeto vacío con Name en blanco, sin excepción"],0,"Sin eager loading (Include), lazy loading habilitado o carga explícita, la propiedad de navegación no cargada queda en su valor por defecto (null para una referencia)."),
   sqr("¿Por qué escribir db.Books.Skip(10).Take(5) sin ningún OrderBy es una práctica arriesgada para paginar?","Porque sin un orden explícito, el orden de las filas devueltas por la base de datos no está garantizado entre consultas, lo que puede producir páginas con filas duplicadas o faltantes",["Porque Skip y Take no pueden usarse juntos en EF Core","Porque siempre lanza una excepción en tiempo de compilación","Porque Take siempre debe ir antes que Skip en la cadena"],0,"Sin ORDER BY, el motor de base de datos no garantiza un orden estable entre ejecuciones; paginar de forma confiable requiere OrderBy antes de Skip/Take."),
   sqr("¿Qué ventaja tiene proyectar con .Select(b => new { b.Title, b.Author.Name }) antes de materializar, en vez de traer la entidad completa?","Solo se transfieren desde la base de datos las columnas realmente necesarias, reduciendo el tráfico de datos y el trabajo de mapeo",["Hace que la consulta deje de traducirse a SQL","Evita tener que declarar un DbSet para esa entidad","Es obligatorio para poder usar Where en la misma consulta"],0,"Seleccionar solo los campos necesarios (en vez de la entidad completa con todas sus columnas y navegaciones) reduce el ancho de banda y el costo de materialización."),
   sqr("¿Qué diferencia hay entre usar Any() y Count() > 0 para comprobar si existen resultados que cumplen una condición?","Any() se traduce a una consulta EXISTS eficiente que se detiene en la primera coincidencia; Count() > 0 cuenta todas las filas que cumplen la condición antes de comparar, siendo potencialmente más costoso en tablas grandes",["Son exactamente equivalentes en rendimiento en cualquier proveedor","Count() > 0 siempre es más rápido porque usa índices exclusivos","Any() no puede usarse dentro de una consulta EF Core"],0,"Any() solo necesita confirmar que existe al menos una fila (EXISTS), mientras que Count() > 0 por definición debe contar coincidencias antes de comparar contra cero."),
   sqr("¿Para qué se usaría FromSqlInterpolated en una consulta de EF Core en vez de LINQ normal?","Para ejecutar una consulta SQL cruda cuando la lógica no puede expresarse con LINQ, parametrizando de forma segura los valores interpolados para evitar SQL injection",["Para deshabilitar el change tracking de toda la aplicación","Para forzar a EF Core a ignorar cualquier índice de la base de datos","Para reemplazar completamente a DbContext"],0,"FromSqlInterpolated permite escribir SQL crudo cuando LINQ no alcanza, pero sigue parametrizando los valores interpolados de forma segura, a diferencia de concatenar strings manualmente."),
   sqr("¿El orden en que se escriben Where, OrderBy y Select en una cadena LINQ afecta si se puede usar Skip/Take correctamente después?","Sí: para que Skip/Take produzcan una paginación determinista, OrderBy debe aplicarse antes de ellos en la composición de la consulta",["No, el orden de los operadores LINQ nunca afecta el resultado final","Sí, pero solo en bases de datos NoSQL, nunca en SQL Server","No, Skip/Take siempre ordenan implícitamente por la clave primaria"],0,"Aunque muchos operadores LINQ pueden reordenarse sin cambiar el resultado, Skip/Take dependen de que ya exista un orden bien definido (vía OrderBy) antes de aplicarse."),
  ]},
 {id:"n04-tracking",title:"Tracking vs NoTracking",
  summary:"Por defecto, EF Core rastrea (change tracking) las entidades devueltas por una consulta para poder detectar cambios y generar UPDATE en SaveChanges. AsNoTracking() desactiva ese seguimiento, evitando el costo de snapshotting, apropiado para consultas de solo lectura. AsNoTrackingWithIdentityResolution añade resolución de identidad (una sola instancia por fila con la misma clave) sin activar el tracking completo.",
  code:"var book = await db.Books.FirstAsync(b => b.Id == id); // tracked\nbook.Title = \"Nuevo título\";\nawait db.SaveChangesAsync(); // genera UPDATE automáticamente\n\nvar readOnly = await db.Books.AsNoTracking().ToListAsync(); // no tracked",
  questions:[
   sqr("Si se modifica una propiedad de una entidad tracked y se llama SaveChanges() sin llamar explícitamente a Update(), ¿qué ocurre?","EF Core detecta el cambio automáticamente comparando contra el snapshot del change tracker y genera un UPDATE solo con las columnas modificadas",["No pasa nada porque hay que llamar a db.Update(book) manualmente siempre antes de SaveChanges","Se lanza una excepción porque las entidades tracked son de solo lectura","Se genera un INSERT duplicado además del UPDATE"],0,"El change tracker guarda un snapshot del estado original al consultar la entidad; al comparar contra el estado actual en SaveChanges, detecta y persiste solo lo modificado."),
   sqr("¿Por qué conviene usar AsNoTracking() en una consulta de solo lectura, como un endpoint GET que solo devuelve datos?","Evita el costo de snapshotting y detección de cambios, mejorando el rendimiento cuando las entidades no se van a modificar ni guardar",["Porque sin AsNoTracking() la consulta no puede serializarse a JSON","Porque el tracking bloquea la tabla en la base de datos hasta hacer commit","Porque AsNoTracking() es obligatorio para poder usar async/await"],0,"El tracking tiene un costo de memoria y CPU (mantener el snapshot original); si nunca se va a llamar a SaveChanges sobre esos datos, ese costo es innecesario."),
   sqr("Si se carga una entidad con AsNoTracking(), se modifica una propiedad en memoria y se llama SaveChanges(), ¿se persiste el cambio?","No directamente: como no está rastreada, hay que adjuntarla explícitamente (Attach/Update) para que EF Core sepa que debe generar un UPDATE",["Sí, EF Core detecta el cambio igual porque siempre revisa la base de datos completa","Sí, siempre que el DbContext siga siendo la misma instancia","No, las entidades no rastreadas son inmutables en tiempo de compilación"],0,"Sin tracking no existe un snapshot contra el cual comparar; EF Core no sabe que esa propiedad cambió a menos que la entidad se vuelva a adjuntar explícitamente al contexto."),
   sqr("Por defecto, sin especificar nada, ¿una consulta de EF Core es tracked o no-tracked?","Tracked: el tracking está activado por defecto salvo que se use AsNoTracking() o se configure lo contrario a nivel de contexto",["No-tracked: hay que llamar a AsTracking() explícitamente para rastrear algo","Depende exclusivamente del proveedor de base de datos usado","Tracked solo para consultas async, no-tracked para consultas síncronas"],0,"El comportamiento por defecto de EF Core es rastrear las entidades devueltas; AsNoTracking() es la forma explícita de optar por lo contrario."),
   sqr("¿Qué aporta AsNoTrackingWithIdentityResolution() frente a un simple AsNoTracking()?","Garantiza que exista una sola instancia en memoria por cada fila con la misma clave primaria dentro del resultado (identity resolution), incluso sin activar el tracking completo",["Activa el tracking completo automáticamente, contradiciendo su nombre","Impide que la consulta incluya relaciones con Include()","Hace que la consulta se ejecute de forma síncrona obligatoriamente"],0,"En un resultado con joins que repiten la misma entidad principal varias veces (por ejemplo, un autor con varios libros), AsNoTracking() simple puede crear instancias duplicadas; la variante con identity resolution las unifica sin pagar el costo completo del tracking."),
   sqr("Si se llama dos veces a la misma consulta tracked (por ejemplo, First(b => b.Id == 5)) sobre el mismo DbContext, ¿EF Core crea dos instancias distintas del objeto Book?","No: el change tracker reutiliza la misma instancia ya rastreada para esa clave primaria (identity resolution del propio tracking), evitando duplicados en memoria",["Sí, siempre crea una instancia nueva en cada consulta, incluso tracked","Sí, pero solo si se usa AsNoTracking()","Depende únicamente del proveedor de base de datos, nunca del contexto"],0,"El tracking mantiene un mapa de identidad: si la clave primaria ya está siendo rastreada por ese contexto, EF Core devuelve la misma instancia en memoria en vez de crear otra."),
   sqr("¿Para qué sirve ChangeTracker.Clear() en un DbContext de larga duración?","Para descartar todas las entidades actualmente rastreadas y liberar memoria, sin necesidad de crear (ni disponer) una nueva instancia de DbContext",["Para eliminar físicamente todos los registros de la base de datos","Para deshacer la última migración aplicada","Para deshabilitar permanentemente el tracking en ese contexto"],0,"ChangeTracker.Clear() (agregado en EF Core 7) vacía el estado de tracking en memoria, útil cuando un contexto vive más tiempo del habitual y acumula demasiadas entidades rastreadas."),
   sqr("Además de AsNoTracking() por consulta, ¿cómo se puede hacer que 'no tracking' sea el comportamiento por defecto de todo un DbContext?","Configurando ChangeTracker.QueryTrackingBehavior = QueryTrackingBehavior.NoTracking a nivel de contexto, y usando AsTracking() en las consultas puntuales que sí necesiten rastrear",["No es posible, AsNoTracking() debe repetirse manualmente en cada consulta sin excepción","Eliminando todos los DbSet del contexto","Marcando cada entidad con el atributo [NotTracked]"],0,"QueryTrackingBehavior a nivel de contexto cambia el comportamiento por defecto de todas sus consultas, permitiendo optar explícitamente por tracking solo donde se necesite con AsTracking()."),
   sqr("¿Qué riesgo de rendimiento existe en un endpoint GET que nunca modifica datos pero deja el tracking activado (comportamiento por defecto) para consultas que devuelven muchas filas?","Se paga el costo de mantener un snapshot de cada entidad devuelta para detección de cambios que nunca se van a usar, desperdiciando memoria y CPU en cada request",["Ninguno, el tracking no tiene ningún costo medible en EF Core","La consulta deja de ejecutarse en la base de datos y se resuelve en memoria","Los resultados quedan cacheados permanentemente entre requests distintos"],0,"Cada entidad tracked implica mantener una copia de su estado original para poder compararla luego; en un endpoint puramente de lectura, ese trabajo no aporta ningún beneficio."),
   sqr("Si se usa .Include(b => b.Author) junto con .AsNoTracking() en la misma consulta, ¿se siguen cargando y poblando correctamente las propiedades de navegación?","Sí: Include() sigue funcionando y poblando las navegaciones normalmente; AsNoTracking() solo afecta si EF Core mantiene un snapshot para detectar cambios, no si carga o no las relaciones",["No, AsNoTracking() es incompatible con Include() y una de las dos se ignora","No, Include() solo funciona en consultas tracked por diseño","Sí, pero solo si se usa AsNoTrackingWithIdentityResolution() en vez de AsNoTracking()"],0,"Tracking y eager loading son conceptos independientes: uno controla si se detectan cambios, el otro qué datos relacionados se traen; se pueden combinar libremente, y es un patrón común para endpoints de lectura con datos relacionados."),
  ]},
 {id:"n04-transactions",title:"Transacciones",
  summary:"Cada llamada a SaveChanges() envuelve automáticamente todas las operaciones pendientes acumuladas en una única transacción implícita: se aplican todas o ninguna. Para agrupar varias llamadas a SaveChanges() (o combinarlas con SQL crudo) en una sola unidad atómica, se usa una transacción explícita con context.Database.BeginTransactionAsync() y se hace Commit/Rollback manualmente. DbUpdateConcurrencyException señala un conflicto de concurrencia optimista detectado mediante un token de concurrencia.",
  code:"using var transaction = await db.Database.BeginTransactionAsync();\ntry\n{\n    db.Books.Add(new Book { Title = \"A\" });\n    await db.SaveChangesAsync();\n\n    db.Authors.Add(new Author { Name = \"B\" });\n    await db.SaveChangesAsync();\n\n    await transaction.CommitAsync();\n}\ncatch\n{\n    await transaction.RollbackAsync();\n    throw;\n}",
  questions:[
   sqr("Si SaveChanges() persiste en una sola llamada 3 inserts y 2 updates a la vez, ¿corren ya dentro de una transacción implícita?","Sí: EF Core envuelve automáticamente todos los cambios de una misma llamada a SaveChanges en una transacción implícita; se aplican todos o ninguno",["No, cada entidad se guarda en su propia transacción independiente dentro de la misma llamada","Solo si se usa SQL Server; en otros proveedores no hay transacción implícita","Solo ocurre si se llama SaveChanges(acceptAllChangesOnSuccess: true) explícitamente"],0,"Por diseño, una sola llamada a SaveChanges es atómica: si alguna operación falla, ninguno de los cambios de esa llamada queda aplicado."),
   sqr("¿Cuándo hace falta una transacción EXPLÍCITA (BeginTransaction) en vez de confiar en la implícita de SaveChanges?","Cuando se necesita agrupar varias llamadas a SaveChanges (o mezclarlas con SQL crudo) como una sola unidad atómica",["Siempre, incluso para guardar cambios con una sola llamada a SaveChanges","Nunca, EF Core lo prohíbe explícitamente en cualquier escenario","Solo para consultas de solo lectura que nunca modifican datos"],0,"La transacción implícita solo cubre una llamada a SaveChanges; si el 'todo o nada' debe abarcar varias llamadas, hace falta controlar la transacción manualmente."),
   sqr("Si SaveChanges() lanza una DbUpdateException a mitad de aplicar varios cambios de una misma llamada, ¿qué ocurre con los cambios de esa llamada?","La transacción implícita hace rollback de todos los cambios de esa llamada; ninguno queda aplicado en la base de datos",["Los cambios previos a la excepción quedan guardados parcialmente en la base de datos","Se reintenta automáticamente hasta 3 veces por defecto sin configuración adicional","La excepción se ignora silenciosamente y continúa con el siguiente cambio"],0,"Al estar todos dentro de la misma transacción implícita, un fallo en cualquier parte revierte el conjunto completo de esa llamada a SaveChanges."),
   sqr("¿Qué indica una DbUpdateConcurrencyException?","Que se detectó un conflicto de concurrencia optimista: el token de concurrencia (por ejemplo una columna [Timestamp]/rowversion) cambió desde que la entidad fue cargada, indicando que otro proceso la modificó mientras tanto",["Que la cadena de conexión a la base de datos es inválida","Que la migración pendiente no se aplicó antes de guardar","Que el usuario actual no tiene permisos para escribir en esa tabla"],0,"EF Core compara el token de concurrencia en el WHERE del UPDATE; si 0 filas se ven afectadas (porque el valor ya cambió), lanza esta excepción en vez de sobreescribir datos a ciegas."),
   sqr("¿Cómo implementa típicamente EF Core el control de concurrencia optimista?","Con un token de concurrencia (marcado con [ConcurrencyCheck] o una columna [Timestamp]/rowversion) que se incluye en la cláusula WHERE del UPDATE; si ninguna fila coincide, se lanza DbUpdateConcurrencyException",["Bloqueando la fila en la base de datos apenas se consulta (locking pesimista) por defecto","Comparando manualmente todas las columnas de la entidad completa siempre, sin configuración adicional","Ejecutando la actualización dentro de un nivel de aislamiento Serializable por defecto"],0,"El enfoque por defecto de EF Core es optimista: no bloquea la fila al leerla, sino que detecta el conflicto recién al intentar guardar, comparando el token de concurrencia."),
   sqr("Dentro del bloque 'using var transaction' del ejemplo, si se llaman dos SaveChangesAsync() pero nunca se llega a CommitAsync(), ¿qué ocurre con esos cambios?","Permanecen pendientes hasta hacer CommitAsync(); si no se confirma (por ejemplo, por una excepción o al hacer Dispose sin Commit), se deshacen",["Quedan aplicados de forma permanente en cuanto se llama a cada SaveChangesAsync()","Solo el primer SaveChangesAsync() queda aplicado, el segundo se ignora","Se aplican automáticamente al finalizar el método, sin necesidad de CommitAsync()"],0,"Los SaveChanges dentro de una transacción explícita no confirman nada por sí solos en la base de datos hasta el Commit; sin él, la transacción se revierte."),
   sqr("¿En qué se diferencia TransactionScope de context.Database.BeginTransaction()?","TransactionScope puede abarcar una transacción ambiente que involucre múltiples DbContext u otros recursos transaccionales; BeginTransaction() ata la transacción a la conexión de un único DbContext",["Son exactamente equivalentes en todos los casos, solo cambia el nombre de la API","BeginTransaction() puede abarcar múltiples bases de datos distintas y TransactionScope no","TransactionScope solo funciona con bases de datos NoSQL"],0,"TransactionScope opera a nivel ambiente y puede coordinar múltiples recursos (incluso distintos contextos o proveedores); BeginTransaction() de EF Core es más simple y se limita a la conexión de ese contexto."),
   sqr("¿Qué devuelve context.Database.BeginTransactionAsync() y qué hay que hacer explícitamente para que el trabajo persista?","Devuelve un IDbContextTransaction; hay que llamar explícitamente a CommitAsync() para confirmar los cambios, o RollbackAsync() para descartarlos",["Devuelve directamente un booleano indicando si la transacción tuvo éxito","No devuelve nada, los cambios se confirman automáticamente al salir del bloque using","Devuelve el número de filas afectadas por todas las operaciones futuras"],0,"El objeto de transacción es quien controla explícitamente cuándo confirmar (Commit) o descartar (Rollback) el trabajo acumulado durante su vigencia."),
   sqr("¿Qué riesgo existe si 'crear un pedido' y 'descontar stock' se hacen con dos llamadas a SaveChanges separadas sin una transacción explícita que las agrupe?","Que un fallo entre ambas llamadas deje datos inconsistentes: por ejemplo, el pedido creado pero el stock sin descontar",["Ninguno, EF Core agrupa automáticamente todas las llamadas a SaveChanges del mismo método en una sola transacción","EF Core detecta y corrige automáticamente cualquier inconsistencia entre ambas operaciones","El segundo SaveChanges se cancela automáticamente si el primero tuvo éxito"],0,"Cada SaveChanges es atómico por sí mismo, pero no hay atomicidad entre llamadas separadas salvo que se agrupen explícitamente en una transacción."),
   sqr("¿Por qué mezclar EnableRetryOnFailure (reintentos automáticos ante fallos transitorios) con una transacción manual iniciada con BeginTransaction requiere envolver todo el bloque en una estrategia de ejecución (CreateExecutionStrategy().ExecuteAsync(...))?","Porque si ocurre un fallo transitorio a mitad de una transacción manual, reintentar solo una parte dejaría la transacción en un estado inconsistente; la estrategia de ejecución sabe cómo reintentar la unidad de trabajo completa (incluida la creación de la transacción) de forma segura",["Porque BeginTransaction no puede usarse junto con async/await bajo ninguna circunstancia","Porque EnableRetryOnFailure elimina automáticamente la necesidad de cualquier transacción explícita","Porque es solo una recomendación de estilo sin ningún efecto real en el comportamiento"],0,"EF Core exige explícitamente esta combinación (y lanza una excepción si se omite) porque un reintento parcial de una transacción manual podría reproducir efectos duplicados o dejarla en un estado indefinido."),
  ]},
 {id:"n04-efficient-queries",title:"Consultas eficientes",
  summary:"El problema N+1 ocurre al ejecutar una consulta para una lista y luego una consulta adicional por cada elemento relacionado, en vez de traerlos juntos con Include()/ThenInclude(). Proyectar solo las columnas necesarias con Select() reduce el tráfico de datos. Paginar con Skip/Take exige un OrderBy previo para ser determinista. Any()/Count()/Sum() se traducen a SQL agregado ejecutado en el servidor, evitando traer todo a memoria.",
  code:"// N+1: una query extra por cada libro dentro del foreach\nvar books = db.Books.ToList();\nforeach (var b in books)\n    Console.WriteLine(db.Authors.First(a => a.Id == b.AuthorId).Name);\n\n// Corregido: una sola consulta con el join\nvar books2 = db.Books.Include(b => b.Author).AsNoTracking().ToList();",
  questions:[
   sqr("¿Qué problema ilustra el primer bloque de código (el foreach con db.Authors.First dentro)?","El problema N+1: se ejecuta una consulta para traer los libros y luego una consulta adicional por cada libro para obtener su autor, en vez de una sola consulta con join",["Se ejecutan todas las consultas en paralelo automáticamente por diseño","EF Core cachea automáticamente los resultados, por lo que no hay impacto real de rendimiento","Es un problema exclusivo de bases de datos NoSQL, no de SQL Server"],0,"Por cada libro del resultado se dispara una consulta adicional a Authors, multiplicando el número de round-trips a la base de datos según la cantidad de libros."),
   sqr("¿Cómo corrige Include(b => b.Author) el problema N+1 del primer bloque?","Genera una única consulta (con JOIN o una segunda consulta ya optimizada, según configuración) que trae los libros junto con sus autores, en vez de una consulta separada por cada libro",["Elimina la necesidad de cargar el autor, dejándolo siempre en null","Convierte automáticamente el bucle foreach en una operación asíncrona","Hace que las consultas siguientes se cacheen indefinidamente en memoria"],0,"Include indica a EF Core que traiga esa relación como parte de la misma operación de consulta, evitando el patrón de una consulta adicional por fila."),
   sqr("¿Para qué sirve ThenInclude() encadenado después de Include()?","Para cargar de forma anticipada una propiedad de navegación anidada, un nivel más profundo que la primera relación incluida",["Para revertir el efecto de Include() anterior en la misma cadena","Para ordenar los resultados por la relación incluida","Para forzar el uso de AsNoTracking() automáticamente"],0,"ThenInclude() extiende el eager loading a relaciones de segundo nivel (por ejemplo, Book -> Author -> Publisher), continuando desde el Include() anterior."),
   sqr("¿Por qué db.Books.Count() es preferible a db.Books.ToList().Count cuando solo se necesita el total de libros?","Count() se traduce a un COUNT(*) ejecutado en el servidor; ToList().Count trae todas las filas completas a memoria y luego cuenta en el cliente",["Son exactamente equivalentes en rendimiento en cualquier escenario","ToList().Count es más rápido porque evita el round-trip a la base de datos","Count() no puede usarse junto con Where() en la misma consulta"],0,"Delegar el conteo al motor de base de datos evita transferir y materializar filas completas solo para saber cuántas hay."),
   sqr("¿Qué riesgo tiene usar Skip/Take para paginar sin aplicar antes un OrderBy?","El orden de las filas no está garantizado entre ejecuciones, por lo que distintas páginas pueden repetir o saltarse filas de forma inconsistente",["Skip/Take lanzan una excepción de compilación si no hay OrderBy previo","No hay ningún riesgo real, el motor de base de datos siempre ordena por la clave primaria","Take deja de funcionar si Skip es mayor que 0"],0,"Sin un ORDER BY explícito, el motor de base de datos no garantiza estabilidad en el orden devuelto, lo que puede corromper una paginación basada en Skip/Take."),
   sqr("¿Qué beneficio aporta proyectar con .Select(b => new { b.Title, b.Author.Name }) antes de materializar, comparado con traer la entidad Book completa?","Solo se transfieren desde la base de datos las columnas realmente solicitadas, reduciendo tráfico de red y el costo de mapear objetos completos innecesarios",["Hace que el resultado deje de poder recorrerse con foreach","Evita tener que declarar Include() para acceder a Author.Name","Convierte automáticamente la consulta en asíncrona"],0,"Proyectar reduce el conjunto de columnas transferidas y materializadas exactamente a lo que la vista o el DTO de salida necesita."),
   sqr("¿Por qué Any() suele ser preferible a Count() > 0 para comprobar si existe al menos un resultado?","Any() se traduce a una consulta EXISTS que se detiene en la primera coincidencia; Count() > 0 debe contar todas las filas que cumplen la condición antes de comparar, siendo potencialmente más costoso",["Any() siempre devuelve resultados en un orden distinto a Count()","Count() > 0 no puede combinarse con Where() en la misma consulta","No hay diferencia real de rendimiento entre ambas formas"],0,"EXISTS puede detenerse apenas encuentra la primera fila que cumple, mientras que un COUNT completo recorre (y cuenta) todas las coincidencias antes de poder comparar contra cero."),
   sqr("¿Para qué sirve AsSplitQuery() al incluir varias colecciones de navegación con Include() en la misma consulta?","Para evitar la explosión cartesiana de un único JOIN gigante (datos duplicados) emitiendo, en su lugar, varias consultas separadas para cada colección incluida",["Para dividir la tabla física en varios archivos en el servidor de base de datos","Para desactivar el change tracking de todas las entidades incluidas","Para ejecutar la consulta en paralelo entre varios servidores de base de datos"],0,"Cuando se incluyen múltiples colecciones a la vez, un solo JOIN puede multiplicar filas por cada combinación; AsSplitQuery() evita eso ejecutando consultas independientes por cada colección incluida."),
   sqr("¿Qué ventaja da una consulta compilada (EF.CompiledQuery) para un query parametrizado que se ejecuta muy frecuentemente?","Evita repetir el costo de traducir la expresión LINQ a SQL en cada ejecución, cacheando ese plan de traducción; es una micro-optimización, no necesaria en la mayoría de los casos",["Hace que la consulta se ejecute completamente en memoria sin tocar la base de datos","Elimina la necesidad de parametrizar los valores de entrada","Convierte automáticamente cualquier consulta en de solo lectura (no-tracking)"],0,"CompiledQuery reduce el overhead de recompilar/traducir la misma forma de consulta una y otra vez, útil solo en rutas de código con muy alta frecuencia de ejecución."),
   sqr("¿Es un patrón razonable combinar .Include(b => b.Author) con .AsNoTracking() en un endpoint GET de solo lectura que necesita mostrar datos relacionados?","Sí: es un patrón común y correcto para endpoints de lectura, cargando las relaciones necesarias sin pagar el costo de tracking innecesario",["No, Include() y AsNoTracking() son mutuamente excluyentes en EF Core","No, combinarlos siempre produce datos duplicados en la respuesta","Sí, pero solo funciona si se usa una consulta SQL cruda en vez de LINQ"],0,"Tracking y eager loading son ortogonales; combinar ambos es habitual y recomendable cuando el endpoint solo necesita leer y devolver datos con sus relaciones."),
  ]},
 {id:"n04-challenge",title:"Reto de datos",
  summary:"Integra DbContext de vida corta, tracking apropiado, carga eficiente de relaciones y consultas asíncronas en un escenario realista de acceso a datos, evitando trabajo bloqueante o innecesario en un endpoint que solo lee información.",
  code:"app.MapGet(\"/api/authors/{id}/books\", async (int id, StoreContext db) =>\n{\n    var author = await db.Authors.FindAsync(id);\n    if (author is null) return Results.NotFound();\n\n    var books = db.Books.Where(b => b.AuthorId == id).ToList();\n    return Results.Ok(books);\n});",
  questions:[
   sqr("¿Qué hace FindAsync(id) antes de consultar la base de datos?","Primero revisa si una entidad con esa clave primaria ya está siendo rastreada en el change tracker local del contexto; solo si no la encuentra ahí, consulta la base de datos",["Siempre va directamente a la base de datos, ignorando cualquier entidad ya cargada en memoria","Ejecuta la consulta en un hilo separado sin usar await","Solo funciona con claves primarias compuestas, nunca con una sola columna"],0,"FindAsync está optimizado para buscar por clave primaria y evita un round-trip a la base de datos si esa entidad ya está en el tracking local del contexto."),
   sqr("¿Por qué conviene usar ToListAsync() en vez de ToList() dentro de este endpoint async?","Para evitar bloquear un hilo del thread pool mientras se espera la operación de I/O de la base de datos, aprovechando correctamente el modelo asíncrono del endpoint",["Porque ToList() no existe en EF Core, solo ToListAsync()","Porque ToListAsync() devuelve resultados distintos a ToList() para la misma consulta","Porque ToList() no puede usarse junto con Where()"],0,"Usar la versión síncrona dentro de un handler async bloquea el hilo mientras espera I/O, desperdiciando capacidad del servidor bajo carga; ToListAsync() libera el hilo durante la espera."),
   sqr("Dado que este endpoint solo lee datos y nunca los modifica, ¿qué agregarían a la consulta de libros para mejorar su rendimiento?","AsNoTracking(), para evitar el costo de mantener un snapshot de cada libro devuelto",["BeginTransaction(), para asegurar consistencia de una lectura simple","Include(b => b.Author).ThenInclude(a => a.Books), generando una referencia circular","ChangeTracker.Clear() antes de ejecutar la consulta"],0,"Al no requerir SaveChanges posterior sobre estas entidades, desactivar el tracking evita trabajo de bookkeeping que no aporta ningún valor en un endpoint puramente de lectura."),
   sqr("¿Podría usarse FindAsync para reemplazar directamente la línea 'db.Books.Where(b => b.AuthorId == id)'?","No: FindAsync solo busca por clave primaria de una entidad concreta; no puede expresar un filtro arbitrario como 'todos los libros cuyo AuthorId sea X', para eso se necesita Where()",["Sí, FindAsync admite cualquier predicado arbitrario igual que Where()","Sí, pero solo si AuthorId también es marcado como clave primaria de Book","No, porque FindAsync no existe para relaciones uno a muchos"],0,"FindAsync está diseñado exclusivamente para localizar una entidad por su clave primaria; buscar por una columna distinta (como una FK) requiere una consulta LINQ normal con Where()."),
   sqr("Si más adelante el código accede a book.Author.Name para cada libro obtenido, sin haber usado Include() ni tener lazy loading configurado, ¿qué ocurre?","Author probablemente sea null porque esa navegación no fue cargada, provocando una NullReferenceException al leer Name",["Author se completa automáticamente porque ya se consultó ese Author antes en el mismo método","Se lanza una excepción de compilación indicando que falta Include()","EF Core genera una consulta adicional automáticamente sin que el desarrollador lo note"],0,"Sin eager, explicit o lazy loading configurados, una propiedad de navegación no consultada explícitamente queda en su valor por defecto (null para un tipo referencia)."),
   sqr("Si se quisiera evitar el problema descrito en la pregunta anterior sin activar lazy loading, ¿qué cambio se haría a la consulta de libros?","Agregar .Include(b => b.Author) a la consulta de Books para cargar esa relación en la misma operación",["Cambiar Where() por First() en la misma línea","Quitar AuthorId de la clase Book","Registrar StoreContext como Singleton en vez de Scoped"],0,"Include() es la forma estándar de asegurar que una relación necesaria esté disponible después de materializar la consulta, sin depender de lazy loading."),
   sqr("Si el autor con ese id existe pero no tiene ningún libro asociado, ¿qué debería devolver este endpoint?","200 OK con un array vacío en el body, porque la consulta de libros es válida y simplemente no hay coincidencias",["404 Not Found, porque no hay libros que mostrar","204 No Content obligatoriamente en vez de un array vacío","400 Bad Request porque el autor no tiene libros"],0,"Un autor sin libros es un resultado perfectamente válido; 404 se reserva aquí para cuando el propio autor (el recurso principal de la ruta) no existe, que ya se maneja en la línea anterior."),
   sqr("¿Necesita este endpoint envolver sus operaciones en una transacción explícita con BeginTransaction?","No: al ser una operación puramente de lectura, sin ninguna llamada a SaveChanges, no hay ningún conjunto de escrituras que deba aplicarse de forma atómica",["Sí, cualquier acceso a más de un DbSet requiere una transacción explícita","Sí, porque FindAsync y Where deben ejecutarse dentro de la misma transacción siempre","No, pero solo si se usa una base de datos en memoria para pruebas"],0,"Las transacciones explícitas resuelven atomicidad entre escrituras; un flujo de solo lectura no tiene ese problema, independientemente de cuántas consultas distintas ejecute."),
   sqr("Para que StoreContext pueda inyectarse como parámetro directamente en este endpoint de Minimal API, ¿qué se necesita haber hecho previamente en Program.cs?","Haber registrado StoreContext en el contenedor de DI, típicamente con builder.Services.AddDbContext<StoreContext>(...), lo que además lo configura con lifetime Scoped",["Nada adicional, cualquier clase puede inyectarse automáticamente sin registro previo","Haber marcado la clase StoreContext con el atributo [Injectable]","Haber declarado StoreContext como una clase estática"],0,"Sin registrar StoreContext (por ejemplo con AddDbContext), el sistema de binding de parámetros de Minimal APIs no podría resolverlo desde el contenedor de DI para inyectarlo en el delegate del endpoint."),
   sqr("Resumiendo las mejoras discutidas (AsNoTracking, ToListAsync, Include), ¿qué combinación refleja mejor un endpoint de solo lectura eficiente sobre datos relacionados?","await db.Books.Where(b => b.AuthorId == id).Include(b => b.Author).AsNoTracking().ToListAsync()",["db.Books.Where(b => b.AuthorId == id).ToList() sin ningún ajuste adicional","await db.Books.ToListAsync() seguido de un Where() en memoria sobre la lista ya materializada","new StoreContext().Books.Where(b => b.AuthorId == id).ToList() creando un contexto nuevo manualmente en cada llamada"],0,"Combina filtrado traducido a SQL, carga eficiente de la relación necesaria, ausencia de tracking innecesario y ejecución verdaderamente asíncrona, coherente con todo lo cubierto en el módulo."),
  ]},
 {id:"n05-authn-authz",title:"Authentication vs authorization",
  summary:"Authentication (autenticación) responde '¿quién eres?': verifica la identidad del cliente. Authorization (autorización) responde '¿qué puedes hacer?': decide si esa identidad ya verificada tiene permiso para una acción concreta. Es la trampa de entrevista más común del módulo: fallar la autenticación produce 401; fallar la autorización (ya autenticado) produce 403. En el pipeline de ASP.NET Core, UseAuthentication() debe ejecutarse antes que UseAuthorization(), porque la autorización necesita que la identidad ya esté establecida en HttpContext.User.",
  code:"app.UseAuthentication(); // primero: ¿quién eres?\napp.UseAuthorization();  // después: ¿qué puedes hacer?\n\n[Authorize] // requiere estar autenticado, cualquier identidad válida\npublic IActionResult Profile() => Ok(User.Identity!.Name);\n\n[Authorize(Roles = \"Admin\")] // requiere además el rol Admin\npublic IActionResult DeleteUser(int id) => ...;",
  questions:[
   sqr("¿Cuál es la diferencia fundamental entre authentication y authorization?","Authentication verifica quién es el cliente (identidad); authorization decide qué puede hacer esa identidad ya verificada (permisos)",["Son sinónimos que se usan indistintamente en ASP.NET Core","Authentication ocurre en el servidor y authorization siempre en el cliente","Authorization siempre ocurre antes que authentication en el pipeline"],0,"Es la distinción central del módulo: primero se establece 'quién eres' y luego, con esa identidad ya conocida, se decide 'qué te está permitido hacer'."),
   sqr("¿Por qué debe ejecutarse app.UseAuthentication() antes que app.UseAuthorization() en Program.cs?","Porque la autorización necesita leer la identidad (ClaimsPrincipal) ya establecida en HttpContext.User, y esa identidad la construye el middleware de autenticación",["Por convención de nombres alfabético, sin ninguna razón funcional","Porque UseAuthorization() elimina automáticamente las cookies de sesión","Porque de lo contrario CORS deja de funcionar"],0,"Si la autorización se evaluara antes de que la autenticación poblara HttpContext.User, no tendría ninguna identidad válida contra la cual comprobar roles, claims o policies."),
   sqr("Un cliente envía un JWT con la firma correcta pero ya expirado. ¿Esto es un fallo de autenticación o de autorización, y qué código corresponde?","Fallo de autenticación (el token ya no es válido como credencial), lo que corresponde a 401",["Fallo de autorización, corresponde a 403","Ninguno de los dos, corresponde a 400 Bad Request","Fallo de autorización, corresponde a 401"],0,"Un token expirado significa que el cliente no puede probar su identidad en ese momento; eso es un problema de autenticación, no de permisos, así que corresponde 401."),
   sqr("Un usuario autenticado con un token válido intenta llamar a DeleteUser, que exige [Authorize(Roles = \"Admin\")], pero su cuenta no tiene ese rol. ¿Qué código corresponde?","403 Forbidden, porque su identidad es válida (está autenticado) pero no tiene el permiso requerido",["401 Unauthorized, porque el rol falta","400 Bad Request, porque el id enviado podría ser inválido","500 Internal Server Error, porque la política de roles falló"],3,"Al estar ya autenticado correctamente, el problema es exclusivamente de permisos: le falta el rol Admin, lo que corresponde exactamente a 403."),
   sqr("¿Autenticarse correctamente en una API garantiza acceso a todos sus endpoints?","No: estar autenticado solo establece la identidad; cada endpoint puede seguir exigiendo su propia autorización (roles, claims o policies) además de esa identidad",["Sí, una vez autenticado el usuario puede acceder a cualquier endpoint sin más comprobaciones","Sí, salvo que el endpoint use HTTPS","No, autenticarse correctamente nunca otorga acceso a ningún endpoint"],1,"Autenticación y autorización son pasos independientes: superar el primero no exime de superar el segundo en cada recurso protegido."),
   sqr("¿Qué exige exactamente un [Authorize] simple, sin Roles ni Policy especificados?","Únicamente que el usuario esté autenticado con cualquier identidad válida; no impone ningún requisito adicional de rol o permiso específico",["Que el usuario tenga el rol 'Admin' por defecto","Que la petición use el verbo GET exclusivamente","Que el usuario haya iniciado sesión hace menos de un minuto"],0,"[Authorize] sin parámetros es la forma más básica de autorización: solo exige autenticación, sin restringir por rol, claim o política específica."),
   sqr("¿Para qué sirve [AllowAnonymous] sobre una acción dentro de un controlador marcado con [Authorize] a nivel de clase?","Para exceptuar esa acción puntual del requisito de autenticación que aplica al resto del controlador, permitiendo acceso anónimo solo ahí",["Para forzar que esa acción también requiera un rol de administrador","Para deshabilitar HTTPS únicamente en esa acción","Para bloquear el acceso a esa acción incluso para usuarios autenticados"],0,"[AllowAnonymous] sobreescribe, para esa acción específica, el [Authorize] heredado del controlador, útil por ejemplo para un endpoint de login dentro de un controlador protegido."),
   sqr("¿Puede una aplicación ASP.NET Core tener registrados varios esquemas de autenticación a la vez (por ejemplo cookies para el navegador y JWT Bearer para clientes de API)?","Sí: se pueden registrar múltiples esquemas simultáneamente y seleccionar cuál aplica por endpoint o por defecto",["No, solo puede existir un esquema de autenticación activo por aplicación","Sí, pero solo si ambos esquemas usan la misma clave de firma","No, mezclar cookies y JWT Bearer está prohibido por el framework"],0,"ASP.NET Core admite registrar múltiples esquemas (cada uno con su propio AddScheme/AddJwtBearer/AddCookie) y decidir, por política o por endpoint, cuál se usa."),
   sqr("¿Quién construye el ClaimsPrincipal disponible en HttpContext.User durante una petición?","El middleware de autenticación, a partir de las credenciales validadas (cookie, token, etc.), antes de que se evalúe cualquier autorización",["El propio desarrollador debe construirlo manualmente en cada acción","El middleware de CORS, como parte de validar el origen de la petición","La base de datos, al ejecutar la primera consulta del request"],0,"UseAuthentication() es responsable de validar las credenciales entrantes y poblar HttpContext.User con la identidad resultante, que luego usa la autorización."),
   sqr("¿Es correcto decir que la autorización en ASP.NET Core se limita únicamente a comprobar roles?","No: además de roles, ASP.NET Core soporta autorización basada en claims arbitrarios y policies completamente personalizadas con lógica propia; los roles son solo uno de varios mecanismos disponibles",["Sí, [Authorize(Roles=...)] es la única forma de autorización que existe","Sí, cualquier lógica de permisos debe implementarse fuera de ASP.NET Core","No, pero solo puede usarse un rol a la vez por usuario"],1,"El sistema de autorización de ASP.NET Core es extensible: roles, claims y policies (con requirements e IAuthorizationHandler personalizados) son todos mecanismos válidos, no solo los roles."),
  ]},
 {id:"n05-identity",title:"Identity",
  summary:"ASP.NET Core Identity es un sistema de membership que gestiona usuarios, contraseñas (nunca en texto plano, siempre hasheadas con salteo), roles, tokens de confirmación/recuperación y bloqueo de cuentas, respaldado típicamente por EF Core (IdentityDbContext). UserManager<TUser> gestiona el CRUD de usuarios/roles/claims; SignInManager<TUser> gestiona el proceso de inicio de sesión en sí (validación de credenciales, cookie de autenticación, bloqueo, 2FA). Por defecto Identity emite cookies, no JWTs; emitir JWTs requiere integrarlo explícitamente con un esquema Bearer.",
  code:"public class AppUser : IdentityUser { public string DisplayName { get; set; } = \"\"; }\npublic class AppDbContext : IdentityDbContext<AppUser> { }\n\nvar result = await userManager.CreateAsync(new AppUser { UserName = \"ada\" }, \"P@ssw0rd!\");\nif (!result.Succeeded)\n    foreach (var error in result.Errors) Console.WriteLine(error.Description);",
  questions:[
   sqr("¿Cómo almacena ASP.NET Core Identity las contraseñas de los usuarios?","Nunca en texto plano: las hashea (con salteo/salt) usando un algoritmo fuerte, y solo guarda ese hash en la columna PasswordHash",["En texto plano dentro de la tabla AspNetUsers, para poder mostrarlas si se olvidan","Cifradas de forma reversible con la misma clave que firma los JWT","En un archivo de configuración separado de la base de datos"],0,"El diseño de Identity asume que ni siquiera el propio sistema debería poder recuperar la contraseña original; solo puede verificar un intento comparando hashes."),
   sqr("¿Qué diferencia hay entre UserManager<TUser> y SignInManager<TUser>?","UserManager gestiona el CRUD de usuarios, roles, claims y tokens; SignInManager gestiona específicamente el proceso de inicio de sesión (validar credenciales, emitir la cookie de autenticación, bloqueo, 2FA)",["Son exactamente lo mismo, SignInManager es solo un alias de UserManager","UserManager solo funciona con roles; SignInManager solo funciona con claims","SignInManager reemplaza por completo la necesidad de UserManager"],0,"Cada uno tiene una responsabilidad distinta: UserManager es la API de administración de cuentas; SignInManager orquesta el flujo de autenticación interactiva sobre esas cuentas."),
   sqr("¿Qué es IdentityDbContext<TUser> y en qué se relaciona con EF Core?","Es un DbContext ya preconfigurado por ASP.NET Core Identity, con el modelo de EF Core listo para las tablas de usuarios, roles, claims, logins y tokens de Identity",["Es un reemplazo completo de DbContext que no usa EF Core internamente","Es una interfaz que solo se usa en pruebas unitarias, nunca en producción","Es un servicio de Azure obligatorio para usar Identity"],0,"IdentityDbContext hereda de DbContext y ya trae declarados los DbSet y la configuración del modelo que Identity necesita para persistir usuarios y datos relacionados."),
   sqr("¿Qué tipo de valor devuelve userManager.CreateAsync(user, password) para indicar si la operación tuvo éxito?","Un IdentityResult, con Succeeded como booleano y una colección Errors con los detalles si falló (por ejemplo, contraseña débil)",["Un simple bool: true si tuvo éxito, false si falló, sin más detalle","El objeto AppUser recién creado directamente, o null si falló","Lanza siempre una excepción si la contraseña no cumple las reglas configuradas"],1,"IdentityResult permite inspeccionar exactamente qué reglas de validación fallaron (por ejemplo, longitud mínima o falta de caracteres especiales) en vez de solo un booleano genérico."),
   sqr("¿Dónde se configuran las reglas de complejidad de contraseña por defecto de Identity (longitud mínima, dígitos, mayúsculas, etc.)?","Mediante services.Configure<IdentityOptions> (o las opciones pasadas a AddIdentity/AddDefaultIdentity), en la sección Password de esas opciones",["No son configurables, siempre exigen exactamente 8 caracteres con un símbolo","Directamente en el archivo appsettings.json sin necesidad de código C#","En el atributo [PasswordRules] sobre la clase AppUser"],0,"IdentityOptions.Password expone propiedades como RequiredLength, RequireDigit, RequireUppercase, etc., configurables al registrar Identity en el contenedor de DI."),
   sqr("¿Para qué sirve el bloqueo de cuenta (account lockout) que ofrece Identity?","Para bloquear temporalmente una cuenta tras un número configurado de intentos fallidos de inicio de sesión, mitigando ataques de fuerza bruta",["Para eliminar permanentemente la cuenta tras el primer intento fallido","Para forzar un cambio de contraseña cada 30 días automáticamente","Para impedir que el usuario cambie su propia contraseña"],0,"El lockout es una defensa contra intentos repetidos de adivinar una contraseña, configurable en MaxFailedAccessAttempts y el tiempo de bloqueo."),
   sqr("¿AddIdentity() por sí solo (sin configuración adicional) hace que la aplicación emita JWTs para autenticar a los clientes?","No: por defecto Identity está pensado para autenticación basada en cookies; emitir JWTs requiere agregar explícitamente un esquema Bearer (o usar los endpoints nativos de Identity API pensados para eso)",["Sí, AddIdentity() configura automáticamente JWT Bearer como esquema por defecto","Sí, pero solo si el proyecto es una Web API y no una app MVC","No, Identity nunca puede combinarse con JWT bajo ninguna circunstancia"],0,"El comportamiento estándar de Identity es cookie-based; para escenarios de API stateless con JWT hace falta una integración adicional explícita."),
   sqr("¿Qué diferencia hay entre asignar un rol a un usuario y crear ese rol en el sistema?","RoleManager<IdentityRole> se encarga de crear/eliminar el rol en sí (como entidad del sistema); userManager.AddToRoleAsync(user, role) asigna un rol ya existente a un usuario concreto",["Son la misma operación, cualquiera de los dos managers hace ambas cosas indistintamente","Los roles se crean automáticamente la primera vez que se asignan a un usuario, sin RoleManager","AddToRoleAsync crea el rol si no existe todavía, sin necesidad de RoleManager"],0,"Gestionar el catálogo de roles disponibles (RoleManager) es una operación distinta de vincular un usuario concreto con uno de esos roles (UserManager.AddToRoleAsync)."),
   sqr("¿Identity incluye soporte nativo para autenticación de dos factores (2FA)?","Sí: SignInManager expone el flujo para generar y validar códigos de dos factores (como TOTP) como parte del proceso de inicio de sesión",["No, 2FA requiere reemplazar completamente el sistema de Identity por otro","Sí, pero solo está disponible contratando un servicio externo de pago","No, hay que implementarlo manualmente desde cero sin ningún soporte del framework"],1,"El soporte de 2FA (habilitación, generación de códigos, recovery codes) forma parte del conjunto de funcionalidades ya incluidas en ASP.NET Core Identity."),
   sqr("¿Es una buena práctica guardar además la contraseña en texto plano en otra columna 'por si acaso', junto al PasswordHash que ya gestiona Identity?","No: nunca se debe almacenar la contraseña en texto plano bajo ninguna circunstancia; todo el propósito del hash es que la contraseña original jamás sea recuperable, ni siquiera por el propio sistema",["Sí, es recomendable como respaldo en caso de que el hash se corrompa","Sí, siempre que esa columna esté marcada como privada en la clase C#","Depende, es aceptable si la base de datos está en una red interna"],0,"Guardar la contraseña en texto plano en cualquier lugar anula por completo la garantía de seguridad que ofrece el hasheo, exponiendo a todos los usuarios ante cualquier fuga de esa columna."),
  ]},
 {id:"n05-jwt",title:"JWT Bearer",
  summary:"Un JWT tiene tres partes separadas por puntos (header.payload.signature), cada una codificada en Base64Url. El payload NO está cifrado por defecto, solo codificado: cualquiera puede decodificarlo y leer sus claims; la firma garantiza integridad (que no fue alterado), no confidencialidad. El middleware JWT Bearer de ASP.NET Core valida issuer, audience, expiración y firma contra la configuración registrada; si algo no coincide, la autenticación falla (401). Los JWT son stateless: no pueden revocarse nativamente antes de expirar sin un mecanismo adicional.",
  code:"builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme)\n    .AddJwtBearer(options =>\n    {\n        options.TokenValidationParameters = new TokenValidationParameters\n        {\n            ValidateIssuer = true,\n            ValidIssuer = \"https://miapi.com\",\n            ValidateAudience = true,\n            ValidAudience = \"mis-clientes\",\n            ValidateLifetime = true,\n            ValidateIssuerSigningKey = true,\n            IssuerSigningKey = new SymmetricSecurityKey(key)\n        };\n    });",
  questions:[
   sqr("¿El payload de un JWT está cifrado por defecto?","No: está solo codificado en Base64Url, no cifrado; cualquiera puede decodificarlo y leer sus claims, por eso no se debe poner información sensible ahí",["Sí, el payload siempre está cifrado con la misma clave que lo firma","Sí, pero solo si la conexión usa HTTPS","No se puede leer el payload sin conocer la clave secreta del emisor"],0,"Base64Url es solo una codificación reversible sin ninguna clave, no un cifrado; la seguridad del JWT depende de la firma (integridad), no de ocultar el contenido."),
   sqr("¿Qué garantiza la firma de un JWT?","Que el token no fue modificado después de haber sido emitido (integridad), verificable con la clave o certificado del emisor",["Que el contenido del payload es confidencial y nadie más puede leerlo","Que el token nunca puede expirar","Que el token fue enviado por HTTPS"],0,"La firma protege contra manipulación (alguien alterando el payload), no contra lectura; confidencialidad requeriría cifrado adicional, que un JWT estándar no aplica por sí solo."),
   sqr("¿Cuáles son las tres partes de un JWT, separadas por puntos?","Header, payload y signature",["Issuer, audience y expiration","Header, body y footer","Claims, roles y policies"],0,"Un JWT compacto tiene la forma header.payload.signature, cada segmento codificado independientemente en Base64Url."),
   sqr("¿Qué logra ValidateLifetime = true en TokenValidationParameters?","Rechaza automáticamente el token si su claim 'exp' (expiración) ya pasó, sin que el código de la aplicación tenga que comprobarlo manualmente",["Hace que el token nunca expire mientras la app esté corriendo","Cifra el payload del token automáticamente","Extiende automáticamente la expiración del token en cada request"],0,"El middleware de validación revisa el timestamp de expiración incluido en el propio token y falla la autenticación si ya venció, como parte del proceso estándar de validación."),
   sqr("Si el claim 'iss' de un token no coincide con ValidIssuer configurado, pero la firma sí es correcta, ¿la autenticación tiene éxito?","No: la autenticación falla (401) igualmente, porque ValidateIssuer exige que el emisor coincida exactamente con el configurado, independientemente de que la firma sea válida",["Sí, basta con que la firma sea válida para que el token se acepte","Sí, pero solo se registra una advertencia en los logs sin rechazar el token","No, pero solo si además ValidateAudience está deshabilitado"],0,"Cada validación configurada (issuer, audience, lifetime, firma) es una condición independiente; todas deben cumplirse para que el token se acepte."),
   sqr("¿Qué diferencia hay entre firmar un JWT con una clave simétrica (HMAC, HS256) y con una asimétrica (RSA/ECDSA, RS256/ES256)?","Con clave simétrica, la misma clave sirve para firmar y validar (por lo que cualquiera con esa clave también podría forjar tokens); con clave asimétrica, el emisor firma con una clave privada y los demás validan solo con la clave pública correspondiente, sin poder firmar",["Son exactamente equivalentes en seguridad, solo cambia el nombre del algoritmo","La clave simétrica siempre es más segura porque es más corta","La clave asimétrica no permite validar la expiración del token"],0,"En escenarios con múltiples servicios validando tokens, usar clave asimétrica evita distribuir un secreto capaz de firmar tokens nuevos a cada validador."),
   sqr("¿Una firma válida garantiza por sí sola que el token no ha expirado?","No: la validación de la firma y la validación de la expiración son comprobaciones independientes; un token perfectamente firmado pero con 'exp' vencido sigue siendo rechazado si ValidateLifetime está activo",["Sí, si la firma es válida el token nunca puede considerarse expirado","Sí, porque la fecha de expiración forma parte de la firma y por tanto la invalida automáticamente","No tiene relación, la expiración solo se comprueba manualmente en el código de la aplicación"],0,"Firma e integridad temporal son criterios distintos: un atacante no puede falsificar la firma, pero un token legítimo perfectamente firmado igual deja de ser válido tras su expiración."),
   sqr("¿Cómo envía típicamente el cliente el JWT en las peticiones subsecuentes a una API protegida?","En el header Authorization, con el formato 'Bearer <token>'",["Como una cookie httpOnly gestionada automáticamente por el navegador","En el query string de cada URL, por ejemplo ?token=xxx","En el body de cada petición GET"],3,"El esquema Bearer estándar espera el token en el header Authorization; el middleware AddJwtBearer está diseñado para leerlo de ese lugar por defecto."),
   sqr("¿Puede el servidor revocar/invalidar un JWT ya emitido antes de que expire, usando solo el mecanismo estándar de JWT?","No de forma nativa: los JWT son stateless y siguen siendo válidos hasta su expiración salvo que se implemente un mecanismo adicional, como una lista de revocación o tokens de vida corta combinados con refresh tokens",["Sí, basta con eliminar el usuario de la base de datos para invalidar todos sus tokens emitidos al instante","Sí, el servidor mantiene automáticamente un registro de todos los tokens válidos","No, y tampoco existe ninguna forma práctica de mitigar este problema"],0,"La naturaleza stateless del JWT (el servidor no guarda una lista de tokens emitidos) es justamente lo que hace que revocarlo antes de tiempo requiera infraestructura adicional explícita."),
   sqr("¿Para qué sirve un refresh token junto a un JWT (access token) de vida corta?","Para obtener un nuevo access token sin que el usuario tenga que volver a iniciar sesión, una vez que el access token de corta duración expira",["Para cifrar el payload del access token","Para reemplazar completamente la necesidad de firmar el access token","Para acortar aún más la vida útil del access token cada vez que se usa"],1,"El patrón access token corto + refresh token más largo permite limitar el daño de un access token filtrado (expira pronto) sin sacrificar la experiencia del usuario, que renueva su sesión con el refresh token."),
  ]},
 {id:"n05-claims-roles",title:"Claims y roles",
  summary:"Un claim es un par nombre-valor sobre el usuario (por ejemplo 'email', 'department') incluido en su ClaimsIdentity/ClaimsPrincipal; los roles en ASP.NET Core se representan internamente como claims de un tipo especial (ClaimTypes.Role). [Authorize(Roles=\"Admin,Manager\")] concede acceso si el usuario tiene AL MENOS UNO de los roles listados (lógica OR), nunca todos a la vez con una sola lista separada por comas.",
  code:"[Authorize(Roles = \"Admin,Manager\")] // OR: alcanza con tener uno de los dos\npublic IActionResult DeleteBook(int id) { ... }\n\nvar claims = new List<Claim>\n{\n    new(ClaimTypes.Name, \"ada\"),\n    new(ClaimTypes.Role, \"Admin\"),\n    new(\"department\", \"Engineering\")\n};",
  questions:[
   sqr("¿Qué significa exactamente [Authorize(Roles = \"Admin,Manager\")]?","Concede acceso si el usuario tiene AL MENOS UNO de esos roles (Admin O Manager), no necesariamente ambos",["Exige que el usuario tenga ambos roles simultáneamente (Admin Y Manager)","Exige que el usuario NO tenga ninguno de esos dos roles","Ignora los roles y solo exige estar autenticado"],0,"Una lista de roles separada por comas dentro de un mismo [Authorize] siempre se evalúa como OR: basta con que el usuario tenga uno cualquiera de los roles listados."),
   sqr("¿Cómo se exige que un usuario tenga DOS roles simultáneamente (lógica AND), en vez de cualquiera de ellos?","Aplicando dos atributos [Authorize(Roles=\"X\")] separados sobre el mismo miembro (uno por cada rol requerido), ya que una única lista separada por comas siempre es OR",["Escribiendo [Authorize(Roles = \"Admin,Manager\")] tal cual, que ya implica AND","No es posible expresar AND entre roles bajo ninguna circunstancia en ASP.NET Core","Usando [Authorize(Roles = \"Admin AND Manager\")] con la palabra AND literal"],0,"Apilar varios [Authorize] hace que cada uno deba superarse por separado (AND entre atributos), mientras que los roles dentro de un mismo atributo siguen evaluándose como OR entre sí."),
   sqr("Conceptualmente, ¿qué es un claim?","Una afirmación en forma de par nombre-valor sobre el usuario (por ejemplo 'email' = 'ada@x.com'), emitida por una parte confiable y parte de su ClaimsPrincipal",["Un permiso binario que solo puede valer true o false","Un método de la clase UserManager","Una tabla de la base de datos que reemplaza a AspNetUsers"],0,"Los claims son la unidad básica de información sobre la identidad autenticada; roles, nombre, email, etc. se modelan todos como claims con distintos tipos."),
   sqr("¿Cómo representa internamente ASP.NET Core los roles de un usuario dentro de su ClaimsPrincipal?","Como claims de un tipo especial (ClaimTypes.Role, o el tipo configurado como RoleClaimType), es decir, los roles son un caso particular de claim, no un mecanismo totalmente aparte",["Como una propiedad separada del objeto User que no tiene relación con los claims","Como una cookie adicional independiente del token o la sesión","Como una tabla en memoria que se reconstruye en cada petición"],0,"Roles y claims comparten la misma infraestructura interna; [Authorize(Roles=...)] en el fondo busca claims de tipo rol dentro del mismo ClaimsPrincipal."),
   sqr("¿Qué diferencia hay entre User.IsInRole(\"Admin\") y User.HasClaim(...)?","IsInRole comprueba específicamente si existe un claim del tipo configurado como rol con ese valor; HasClaim permite comprobar cualquier tipo y valor de claim arbitrario, de forma más general",["Son exactamente equivalentes en cualquier escenario","IsInRole funciona con cualquier claim; HasClaim solo funciona con roles","HasClaim solo puede usarse dentro de Razor Pages, no en controladores"],0,"IsInRole es un atajo especializado sobre el claim de tipo rol; HasClaim es la herramienta genérica para comprobar cualquier claim, como el 'department' del ejemplo."),
   sqr("¿Puede usarse un claim personalizado como 'department' para restringir el acceso a un endpoint?","Sí, pero no directamente con [Authorize(Roles=...)]; requiere autorización basada en policies (por ejemplo RequireClaim o un requirement personalizado) que sepa leer ese claim específico",["No, [Authorize] solo puede evaluar los roles predefinidos del sistema","Sí, automáticamente, cualquier claim se evalúa igual que un rol sin configuración adicional","No, los claims personalizados solo sirven para mostrarse en la interfaz de usuario"],0,"Los claims arbitrarios necesitan una policy explícita (o lógica de autorización personalizada) que los lea, ya que [Authorize(Roles=...)] está limitado específicamente al claim de tipo rol."),
   sqr("¿Puede un cliente simplemente agregar un header o campo adicional a su petición para 'auto-otorgarse' un rol vía claims?","No: los claims provienen de la identidad ya validada por el servidor (por ejemplo, incluidos y firmados dentro de un JWT, o construidos por Identity al iniciar sesión), no de datos arbitrarios que el cliente agregue a la petición",["Sí, basta con que el cliente incluya el claim deseado en cualquier header de la petición","Sí, si el cliente edita manualmente las cookies del navegador","Depende, funciona si la API no usa HTTPS"],0,"Los claims válidos vienen de la fuente de identidad confiable que el servidor ya validó (token firmado, sesión de Identity); un valor añadido arbitrario por el cliente fuera de esa fuente no se convierte en un claim reconocido."),
   sqr("¿Qué relación hay entre ClaimsPrincipal y ClaimsIdentity?","Un ClaimsPrincipal puede envolver una o más ClaimsIdentity (por ejemplo, de distintos esquemas de autenticación), cada una con su propio conjunto de claims",["Son exactamente la misma clase con dos nombres distintos","ClaimsIdentity envuelve múltiples ClaimsPrincipal, al revés de lo habitual","ClaimsPrincipal solo existe en Identity, ClaimsIdentity solo en JWT Bearer"],0,"HttpContext.User es un ClaimsPrincipal que agrupa una o más identidades (ClaimsIdentity), útil cuando coexisten varios esquemas de autenticación."),
   sqr("Si el rol de un usuario cambia en la base de datos, ¿ese cambio se refleja automáticamente en un JWT que ya fue emitido antes del cambio?","No: un token ya emitido conserva los claims que tenía al momento de emitirse; el cambio de rol solo se reflejará en tokens emitidos (o refrescados) después de esa actualización",["Sí, el servidor actualiza automáticamente el contenido de tokens ya emitidos y en circulación","Sí, porque los JWT consultan la base de datos en cada request para verificar los roles actuales","No, y además nunca se reflejará ni siquiera en un token nuevo"],0,"Como los JWT son stateless y su contenido queda fijo al firmarse, cualquier cambio de rol solo aplica a partir de la próxima vez que se emita un token nuevo para ese usuario."),
   sqr("¿Para qué sirve configurar RoleClaimType en TokenValidationParameters?","Para indicar explícitamente qué tipo de claim dentro del token debe tratarse como 'el rol' al evaluar [Authorize(Roles=...)], necesario cuando el emisor del JWT usa un nombre de claim distinto al predeterminado",["Para deshabilitar por completo la validación de roles","Para cifrar únicamente el claim de rol dentro del payload","Para convertir automáticamente cualquier claim en un rol válido"],0,"Si el JWT usa, por ejemplo, un claim llamado 'roles' en vez del tipo por defecto que ASP.NET Core espera, hay que indicárselo explícitamente para que IsInRole/[Authorize(Roles=...)] lo reconozcan correctamente."),
  ]},
 {id:"n05-policies",title:"Policies",
  summary:"La autorización basada en policies define requisitos con nombre mediante AddAuthorization/AddPolicy, combinando uno o más IAuthorizationRequirement evaluados por un IAuthorizationHandler registrado en DI. [Authorize(Policy=\"...\")] aplica una policy nombrada a un endpoint; es más flexible que Roles porque permite reglas arbitrarias (edad mínima, pertenencia a un recurso, horario, etc.). Por defecto, TODOS los requirements agregados a una policy deben cumplirse (AND) para que la policy pase.",
  code:"builder.Services.AddAuthorization(options =>\n{\n    options.AddPolicy(\"MinimumAge18\", policy =>\n        policy.Requirements.Add(new MinimumAgeRequirement(18)));\n});\nbuilder.Services.AddSingleton<IAuthorizationHandler, MinimumAgeHandler>();\n\npublic class MinimumAgeRequirement(int age) : IAuthorizationRequirement { public int MinimumAge { get; } = age; }\n\npublic class MinimumAgeHandler : AuthorizationHandler<MinimumAgeRequirement>\n{\n    protected override Task HandleRequirementAsync(AuthorizationHandlerContext context, MinimumAgeRequirement requirement)\n    {\n        var birthDateClaim = context.User.FindFirst(\"birthdate\");\n        if (birthDateClaim is not null && EsMayorDeEdad(birthDateClaim.Value, requirement.MinimumAge))\n            context.Succeed(requirement);\n        return Task.CompletedTask;\n    }\n}",
  questions:[
   sqr("Además de declarar la policy con AddPolicy, ¿qué más hace falta para que MinimumAgeHandler realmente se ejecute?","Registrar el handler en el contenedor de DI, por ejemplo con services.AddSingleton<IAuthorizationHandler, MinimumAgeHandler>()",["Nada más, declarar el requirement en AddPolicy ya activa automáticamente cualquier handler existente","Marcar la clase MinimumAgeHandler con [Authorize] directamente","Agregar el handler como middleware con app.Use()"],0,"El sistema de autorización descubre los handlers a través de la inyección de dependencias; sin registrarlo explícitamente como IAuthorizationHandler, nunca se invoca aunque el requirement exista."),
   sqr("¿Qué logra llamar a context.Succeed(requirement) dentro de HandleRequirementAsync?","Marca ese requirement específico como satisfecho; si la policy tiene varios requirements, todos deben marcarse como exitosos (u otro handler debe hacerlo) para que la policy completa pase",["Aprueba automáticamente cualquier otra policy que el usuario intente usar después","Finaliza inmediatamente la petición HTTP con un 200 OK","Elimina el requirement de la policy para futuras evaluaciones"],0,"Succeed() marca ese requirement puntual como cumplido; el resultado final de la policy depende de que TODOS sus requirements terminen satisfechos."),
   sqr("Si HandleRequirementAsync termina sin llamar ni a Succeed() ni a Fail() para ese requirement, ¿la autorización se considera exitosa?","No: por defecto se considera que el requirement no se cumplió (autorización fallida), ya que el éxito debe señalizarse explícitamente con Succeed()",["Sí, por defecto se asume éxito si no hay ningún error explícito","Sí, pero solo si el usuario está autenticado con cualquier identidad","Depende del código de estado HTTP configurado para esa ruta"],0,"El framework no asume éxito por omisión; si ningún handler llama a Succeed() para un requirement dado, ese requirement (y por tanto la policy) no se considera satisfecho."),
   sqr("¿Cuándo conviene preferir una policy personalizada sobre un simple [Authorize(Roles=\"Admin\")]?","Cuando la regla no puede expresarse como un simple chequeo de rol/claim estático, por ejemplo lógica de negocio (edad mínima) o autorización basada en el recurso específico que se está accediendo",["Nunca, [Authorize(Roles=...)] siempre puede expresar cualquier regla de negocio","Solo cuando la aplicación no usa ASP.NET Core Identity","Siempre, los roles están obsoletos en ASP.NET Core moderno"],0,"Las policies con requirements personalizados permiten lógica arbitraria; los roles son apropiados solo para reglas estáticas simples basadas en pertenencia a un grupo."),
   sqr("¿Para qué sirve IAuthorizationService.AuthorizeAsync(User, resource, policyName) frente a un simple [Authorize(Policy=...)] de atributo?","Permite evaluar una policy contra una instancia concreta de un recurso (por ejemplo, comprobar si el usuario actual es el dueño de ESE documento específico ya cargado desde la base de datos), no solo contra claims estáticos del usuario",["Es exactamente equivalente a [Authorize(Policy=...)], solo cambia la sintaxis","Solo puede usarse para roles, nunca para requirements personalizados","Sirve únicamente para autorización basada en horarios del día"],0,"La autorización basada en recursos necesita el objeto concreto en memoria (por ejemplo tras hacer un Find en la base de datos) para poder comparar, algo que un atributo declarativo estático no puede hacer por sí solo."),
   sqr("¿Qué logra configurar options.FallbackPolicy = new AuthorizationPolicyBuilder().RequireAuthenticatedUser().Build()?","Que, por defecto, todo endpoint sin ninguna otra política de autorización explícita exija igualmente estar autenticado, salvo que se marque con [AllowAnonymous]",["Que todos los endpoints queden completamente públicos por defecto","Que se elimine la necesidad de declarar [Authorize] en cualquier controlador que sí lo necesite explícitamente","Que se deshabilite por completo el sistema de autorización"],0,"FallbackPolicy cambia el comportamiento por defecto de la aplicación: en vez de 'público salvo que se proteja', pasa a ser 'protegido salvo que se marque explícitamente como público'."),
   sqr("Si una policy tiene dos requirements distintos agregados con policy.Requirements.Add(...), ¿basta con que se cumpla uno de los dos para que la policy pase?","No: por defecto se exige que TODOS los requirements agregados a una policy se cumplan (lógica AND), no que baste con uno solo",["Sí, por defecto basta con que cualquiera de los requirements se cumpla (lógica OR)","Depende del orden en que se agregaron los requirements","No, solo se evalúa el último requirement agregado, los anteriores se ignoran"],1,"El comportamiento estándar del sistema de autorización de ASP.NET Core es exigir el cumplimiento de todos los requirements de una policy para considerarla superada."),
   sqr("¿Se pueden combinar RequireRole(), RequireClaim() y un requirement personalizado dentro de la misma policy usando AuthorizationPolicyBuilder?","Sí: la API fluida de AuthorizationPolicyBuilder permite mezclar libremente distintos tipos de requisitos (roles, claims, requirements a medida) dentro de una misma policy",["No, cada policy solo puede usar un único tipo de requisito","Sí, pero solo si todos son del tipo Roles","No, RequireClaim() está reservado exclusivamente para Identity"],0,"AuthorizationPolicyBuilder está diseñado precisamente para componer distintos tipos de reglas en una sola policy con nombre, reutilizable en varios endpoints."),
   sqr("Si dos handlers distintos están registrados para el MISMO requirement, ¿es necesario que ambos llamen a Succeed() para que el requirement se considere cumplido?","No: basta con que UNO cualquiera de los handlers registrados para ese requirement llame a Succeed(), salvo que algún handler llame explícitamente a Fail(), lo que fuerza el fallo total sin importar los demás",["Sí, todos los handlers registrados para ese requirement deben llamar a Succeed() sin excepción","No importa, el resultado se decide siempre por el primer handler que se ejecuta, ignorando a los demás","Sí, y además deben ejecutarse en un orden estrictamente secuencial predecible"],0,"Múltiples handlers para el mismo requirement representan caminos alternativos válidos de cumplirlo; con que uno tenga éxito alcanza, a menos que otro handler invoque Fail() explícitamente."),
   sqr("¿Una policy se evalúa una sola vez al iniciar sesión, o en cada petición al endpoint protegido?","En cada petición: la autorización se ejecuta como parte del pipeline de cada request entrante, evaluando el estado y los claims actuales, no solo una vez al momento del login",["Solo una vez, al momento de iniciar sesión, y el resultado se cachea para siempre","Solo cuando el token JWT se renueva explícitamente","Nunca se reevalúa automáticamente, hay que forzarlo manualmente en cada acción"],0,"Cada request pasa por el middleware de autorización, que vuelve a evaluar la policy correspondiente contra el HttpContext.User de ese momento."),
  ]},
 {id:"n05-cors-csrf",title:"CORS y CSRF",
  summary:"CORS es un mecanismo aplicado y verificado por el NAVEGADOR: el servidor solo declara, vía headers, qué orígenes pueden leer una respuesta desde JavaScript; herramientas como curl o Postman ignoran esa restricción por completo. CSRF es un ataque distinto: aprovecha que el navegador adjunta automáticamente las cookies de sesión del usuario autenticado a peticiones hacia ese sitio, aunque se originen desde otra página maliciosa; se mitiga con anti-forgery tokens o cookies SameSite. Access-Control-Allow-Origin: * no puede combinarse con credenciales.",
  code:"builder.Services.AddCors(options =>\n{\n    options.AddPolicy(\"Frontend\", policy =>\n        policy.WithOrigins(\"https://miapp.com\")\n              .AllowAnyHeader()\n              .AllowAnyMethod());\n});\n\n// orden: routing -> UseCors -> autenticación/autorización -> endpoints\napp.UseRouting();\napp.UseCors(\"Frontend\");\napp.UseAuthentication();\napp.UseAuthorization();",
  questions:[
   sqr("¿Quién aplica realmente las restricciones de CORS?","El navegador del cliente: es quien bloquea que JavaScript de otro origen lea la respuesta si el servidor no la permitió explícitamente vía headers",["El servidor rechaza la petición antes de procesarla siempre","Un firewall de red intermedio entre cliente y servidor","La base de datos, al validar el origen de la conexión"],0,"El servidor solo envía headers indicando qué está permitido; es el navegador quien decide, con esa información, si permite que el JavaScript de la página lea la respuesta."),
   sqr("¿Una política CORS restrictiva protege a la API de que herramientas como curl o Postman la llamen directamente?","No: CORS es una restricción aplicada por navegadores; herramientas de línea de comandos u otros servidores pueden llamar al endpoint sin que CORS los detenga en absoluto",["Sí, CORS bloquea cualquier cliente que no sea un navegador autorizado","Sí, siempre que el servidor use HTTPS","Depende del sistema operativo desde el que se ejecute curl"],0,"CORS no es una medida de seguridad del lado del servidor sobre quién puede llamar al endpoint; es una relajación controlada de una restricción que solo existe dentro de navegadores."),
   sqr("¿Puede combinarse AllowAnyOrigin() con AllowCredentials() en una política CORS?","No: el navegador rechaza esa combinación por seguridad; para permitir credenciales hay que especificar orígenes concretos con WithOrigins, no un comodín",["Sí, es la configuración estándar recomendada para producción","Sí, pero solo funciona en conexiones HTTP, no HTTPS","No, pero únicamente en Chrome; otros navegadores sí la permiten"],0,"Permitir cualquier origen junto con el envío de credenciales sería equivalente a exponer datos autenticados a cualquier sitio; la especificación CORS prohíbe expresamente esa combinación."),
   sqr("¿Qué es lo que explota específicamente un ataque CSRF?","Que el navegador adjunta automáticamente las cookies de sesión del usuario autenticado a peticiones hacia ese sitio, incluso si la petición se originó desde una página maliciosa distinta",["Que el atacante roba directamente la contraseña del usuario mediante phishing","Que el servidor no valida correctamente el formato JSON recibido","Que el token JWT del usuario no está firmado correctamente"],0,"CSRF no necesita robar ninguna credencial: se aprovecha de que el navegador, por diseño, adjunta cookies existentes a cualquier petición hacia ese dominio, sin importar desde dónde se originó."),
   sqr("¿Una API que usa exclusivamente Bearer tokens en el header Authorization (sin cookies) tiene la misma exposición a CSRF clásico que una basada en cookies de sesión?","Generalmente no de la misma forma: como el navegador no adjunta automáticamente un header Authorization personalizado entre sitios distintos, un atacante no puede forzar esa petición autenticada solo con un CSRF clásico basado en formularios/imágenes",["Sí, exactamente la misma exposición sin ninguna diferencia","No, porque los Bearer tokens son inmunes a cualquier tipo de ataque por diseño","Sí, pero solo si la API no usa HTTPS"],0,"El vector clásico de CSRF depende de un envío automático de credenciales por el navegador (cookies); un header Authorization debe ser agregado explícitamente por el JavaScript del propio sitio legítimo, lo que un atacante externo no puede forzar de la misma manera."),
   sqr("¿Cómo funciona conceptualmente un anti-forgery token (por ejemplo [ValidateAntiForgeryToken] en ASP.NET Core)?","El servidor entrega un token ligado a la sesión del usuario que debe reenviarse en la petición; si la petición no incluye ese token exacto (algo que un sitio atacante externo no puede obtener), se rechaza",["Cifra el body completo de cada petición del formulario","Bloquea automáticamente todas las peticiones que no usen HTTPS","Reemplaza por completo la necesidad de autenticar al usuario"],0,"El token anti-forgery demuestra que la petición realmente se generó desde una página servida por la propia aplicación (que conoce el token), no desde un origen externo desconocido."),
   sqr("¿Qué efecto tiene marcar una cookie con SameSite=Strict o SameSite=Lax?","Restringe si esa cookie se envía junto con peticiones que se originan desde un sitio distinto (cross-site), mitigando el vector clásico de CSRF a nivel de navegador",["Cifra el contenido de la cookie automáticamente","Hace que la cookie nunca expire","Obliga a que la cookie solo pueda leerse desde JavaScript, nunca desde el servidor"],0,"SameSite es un atributo de cookie que el navegador respeta para decidir si la adjunta en peticiones cross-site, reduciendo directamente la superficie de ataque de CSRF."),
   sqr("En el pipeline mostrado, ¿por qué app.UseCors() se coloca después de app.UseRouting() y antes de app.UseAuthorization()?","Porque CORS necesita que el endpoint ya esté resuelto por el routing para saber a qué política aplicar, y debe evaluarse antes de que se ejecute la autorización o el propio endpoint",["Por una convención de estilo sin ningún efecto funcional real","Porque UseCors() debe ejecutarse siempre antes que UseRouting()","Porque de lo contrario JWT Bearer deja de funcionar por completo"],1,"El orden documentado del pipeline (Routing -> CORS -> Auth -> Endpoints) asegura que la política CORS correcta (posiblemente específica del endpoint) se aplique antes de ejecutar cualquier lógica protegida."),
   sqr("Si un frontend en https://otraweb.com intenta hacer fetch() a esta API sin que su origen esté en WithOrigins, ¿qué ocurre?","El navegador bloqueará que el JavaScript de ese frontend lea la respuesta (aunque el servidor sí la procesó), mostrando un error de CORS en la consola del navegador",["El servidor rechaza la petición antes de ejecutar ningún código","La petición nunca llega a la red, se cancela localmente antes de salir del navegador","No ocurre nada especial, la respuesta se lee con normalidad"],0,"El servidor típicamente sí procesa la petición (salvo un preflight rechazado); lo que falla es que el navegador impide que el script que la originó pueda leer esa respuesta, por no estar autorizado ese origen."),
   sqr("¿CORS es una medida real de seguridad que protege los datos de la API, o solo una relajación controlada de una restricción del navegador?","Es una relajación controlada de la restricción same-origin del navegador; no reemplaza la autenticación ni la autorización como medidas reales de seguridad de la API",["Es la principal medida de seguridad de cualquier API y basta por sí sola","Es completamente irrelevante para la seguridad y solo afecta el rendimiento","Reemplaza por completo la necesidad de usar HTTPS"],0,"CORS existe para permitir, de forma controlada, que ciertos frontends distintos consuman la API desde el navegador; la protección real de los datos sigue dependiendo de autenticación, autorización y buenas prácticas del backend."),
  ]},
 {id:"n05-secrets",title:"Secretos seguros",
  summary:"En desarrollo, User Secrets (dotnet user-secrets) evita comitear cadenas de conexión o claves al control de versiones, guardándolas en texto plano fuera del repositorio, en el perfil del usuario. NO están cifrados: su propósito es solo evitar el commit accidental, no la confidencialidad. En producción, los secretos deben vivir en un almacén dedicado (Azure Key Vault, AWS Secrets Manager, variables de entorno gestionadas por la plataforma), nunca en appsettings.json ni hardcodeados en el código fuente.",
  code:"dotnet user-secrets init\ndotnet user-secrets set \"ConnectionStrings:Default\" \"Server=...;Password=...\"\n\n// se lee igual que cualquier otra configuración\nvar cs = builder.Configuration.GetConnectionString(\"Default\");",
  questions:[
   sqr("¿Dónde se almacenan realmente los User Secrets configurados con 'dotnet user-secrets set'?","En un archivo JSON fuera del árbol del proyecto, dentro de una carpeta del perfil del usuario, identificado por un UserSecretsId declarado en el .csproj",["Dentro de appsettings.json, cifrado automáticamente al guardarlo","En una tabla de la propia base de datos de la aplicación","En una variable de entorno permanente del sistema operativo"],0,"El propósito de guardarlos fuera del repositorio del proyecto es justamente que nunca terminen comiteados por accidente junto con el código fuente."),
   sqr("¿Los User Secrets están cifrados en disco?","No: se almacenan en texto plano fuera del repositorio; su propósito es solo evitar comitearlos por accidente al control de versiones, no cifrarlos",["Sí, se cifran automáticamente con la clave del usuario de Windows","Sí, pero solo en macOS y Linux, no en Windows","Sí, usando el mismo certificado que firma los JWT de la aplicación"],1,"User Secrets es una herramienta de conveniencia para desarrollo local, no un mecanismo de cifrado; su valor está en mantener los secretos fuera del repositorio de código."),
   sqr("¿Está pensado el sistema de User Secrets para usarse en producción?","No: es una herramienta exclusivamente para desarrollo local; en producción se debe usar un almacén de secretos real o variables de entorno gestionadas por la plataforma de hosting",["Sí, es la forma recomendada de gestionar secretos también en producción","Sí, siempre que el servidor de producción tenga instalado el SDK de .NET","No, pero solo porque es más lento que leer appsettings.json"],0,"User Secrets depende del perfil de usuario de la máquina de desarrollo; no está diseñado para el modelo de despliegue, escalado ni seguridad que exige un ambiente de producción."),
   sqr("¿Es aceptable comitear una cadena de conexión con contraseña directamente dentro de appsettings.json en el repositorio?","No: cualquier secreto (contraseñas, claves de API, cadenas de conexión) nunca debe comitearse en texto plano en el control de versiones, sin importar si el repositorio es privado",["Sí, siempre que el repositorio sea privado y de la organización","Sí, si se agrega un comentario indicando que es solo para desarrollo","Depende del proveedor de base de datos utilizado"],1,"Un repositorio privado igual puede filtrarse, ser clonado por más personas de las previstas, o quedar expuesto en el historial aunque se elimine después; los secretos deben mantenerse fuera del código versionado siempre."),
   sqr("¿Por qué una variable de entorno configurada en el servidor de producción puede sobrescribir el valor de un secreto definido en appsettings.json, sin cambiar el código?","Porque el pipeline de configuración de ASP.NET Core aplica los proveedores en orden y los agregados después (como variables de entorno) sobrescriben a los anteriores (como appsettings.json) para la misma clave",["Porque appsettings.json se ignora automáticamente en producción sin ninguna configuración adicional","Porque las variables de entorno solo funcionan si appsettings.json no existe en absoluto","No es posible, hay que modificar appsettings.json directamente para producción"],0,"Este orden de precedencia es justamente lo que permite tener un valor placeholder en appsettings.json para desarrollo y que producción lo sobrescriba con el secreto real vía variables de entorno o un almacén como Key Vault."),
   sqr("¿Qué ventaja aporta integrar Azure Key Vault (u otro almacén de secretos) como proveedor de configuración de la aplicación?","Permite leer secretos en tiempo de ejecución desde un almacén centralizado, con control de acceso y auditoría, en vez de guardarlos en archivos locales o variables de entorno sueltas por servidor",["Elimina por completo la necesidad de HTTPS en la aplicación","Hace que la aplicación deje de necesitar un DbContext","Convierte automáticamente todos los endpoints en públicos"],0,"Un almacén dedicado centraliza y audita el acceso a los secretos, además de facilitar rotarlos sin tener que redistribuir archivos de configuración a cada instancia."),
   sqr("¿Qué hace exactamente 'dotnet user-secrets set \"ConnectionStrings:Default\" \"...\"' en el ejemplo?","Guarda ese valor en el almacén de User Secrets local asociado al UserSecretsId del proyecto, accesible luego a través de builder.Configuration como cualquier otra clave de configuración",["Modifica directamente el archivo appsettings.json del proyecto","Crea una nueva migración de base de datos con ese nombre de conexión","Publica la aplicación usando esa cadena de conexión en producción"],0,"El comando set escribe la clave y su valor en el archivo secrets.json local (fuera del repo); la aplicación luego los lee de forma transparente junto con el resto de la configuración."),
   sqr("Si un secreto ya fue comiteado por error a un repositorio y luego se agrega ese archivo a .gitignore, ¿queda resuelto el problema de seguridad?","No: .gitignore solo evita que se incluya en commits futuros; el secreto ya expuesto en el historial debe rotarse/invalidarse, no basta con dejar de rastrear el archivo hacia adelante",["Sí, .gitignore elimina automáticamente el archivo de todos los commits anteriores","Sí, siempre que se haga un nuevo commit inmediatamente después","No, pero solo si el repositorio es público, en uno privado no importa"],0,"El historial de Git conserva versiones anteriores del archivo salvo que se reescriba explícitamente; y aun reescribiéndolo, cualquiera que ya haya clonado el repo pudo haber visto el secreto, así que rotarlo es la única mitigación confiable."),
   sqr("¿Es recomendable reutilizar exactamente las mismas claves/secretos entre los ambientes de desarrollo, staging y producción?","No: usar secretos distintos por ambiente limita el impacto si uno de ellos se filtra o es comprometido, sin afectar a los demás",["Sí, simplifica la configuración y no representa ningún riesgo","Sí, siempre que todos los ambientes usen HTTPS","Depende únicamente del proveedor de base de datos"],0,"Aislar los secretos por ambiente es una práctica básica de defensa en profundidad: comprometer las credenciales de staging, por ejemplo, no debería dar acceso a producción."),
   sqr("Aunque nunca se comitee a un repositorio, ¿por qué sigue siendo mala práctica hardcodear un API key como literal directamente en un archivo .cs?","Porque queda embebido en el ensamblado compilado (recuperable con un descompilador) y mezclado con el código fuente, dificultando rotarlo, auditarlo o compartir el código sin exponerlo",["Porque C# no permite declarar strings constantes con datos sensibles","Porque afecta negativamente el rendimiento de la aplicación en tiempo de ejecución","Porque el compilador rechaza compilar el proyecto en ese caso"],0,"Aun sin llegar al control de versiones, un secreto embebido en el binario compilado sigue siendo extraíble y queda acoplado al ciclo de vida y distribución del código, en vez de gestionarse de forma centralizada y rotable."),
  ]},
 {id:"n05-challenge",title:"Reto de seguridad",
  summary:"Integra autenticación JWT, autorización basada en roles/policies, CORS y manejo seguro de secretos en el diseño de un endpoint protegido, aplicando coherentemente cuándo corresponde 401 frente a 403 y por qué cada pieza de configuración existe.",
  code:"builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme)\n    .AddJwtBearer(options =>\n    {\n        options.TokenValidationParameters = new TokenValidationParameters\n        {\n            ValidateIssuer = true,\n            ValidIssuer = builder.Configuration[\"Jwt:Issuer\"],\n            ValidateAudience = true,\n            ValidAudience = builder.Configuration[\"Jwt:Audience\"],\n            ValidateLifetime = true,\n            IssuerSigningKey = new SymmetricSecurityKey(\n                Encoding.UTF8.GetBytes(builder.Configuration[\"Jwt:Key\"]!))\n        };\n    });\n\nbuilder.Services.AddAuthorization(options =>\n    options.AddPolicy(\"CanManageOrders\", p => p.RequireRole(\"Admin\", \"Manager\")));\n\napp.MapPost(\"/api/orders/{id}/cancel\", (int id) => Results.Ok())\n   .RequireAuthorization(\"CanManageOrders\");",
  questions:[
   sqr("Un cliente llama a POST /api/orders/5/cancel sin incluir ningún header Authorization. ¿Qué código debería recibir?","401 Unauthorized, porque no hay ninguna credencial que autenticarlo",["403 Forbidden, porque le falta la policy CanManageOrders","400 Bad Request, porque falta un header obligatorio","404 Not Found, porque el endpoint requiere autenticación para existir"],0,"Sin ningún token, el cliente ni siquiera tiene una identidad establecida; eso es exactamente un problema de autenticación, no de permisos."),
   sqr("El cliente envía un JWT válido y no expirado, pero su cuenta no tiene el rol Admin ni Manager. ¿Qué código corresponde?","403 Forbidden, porque está autenticado correctamente pero no cumple la policy CanManageOrders",["401 Unauthorized, porque el token es inválido","400 Bad Request, porque el id del pedido podría no existir","500 Internal Server Error, porque la policy lanza una excepción al fallar"],0,"Al tener una identidad válida pero sin los roles requeridos por la policy, el problema es de permisos, no de identidad: corresponde 403."),
   sqr("¿De dónde obtiene la clave de firma (IssuerSigningKey) este código, y por qué es preferible a escribirla como literal en Program.cs?","De builder.Configuration[\"Jwt:Key\"], que en desarrollo puede venir de User Secrets y en producción de variables de entorno o un almacén como Key Vault; así nunca queda hardcodeada ni comiteada en el código fuente",["De una constante embebida directamente en el archivo Program.cs","Del propio token JWT que envía el cliente en cada petición","De la base de datos de la aplicación, consultada en cada request"],0,"Leerla desde configuración permite que cada ambiente use su propio valor gestionado de forma segura, sin tocar el código ni exponer la clave en el repositorio."),
   sqr("¿Qué logra RequireRole(\"Admin\", \"Manager\") dentro de la policy CanManageOrders?","Exige que el usuario tenga al menos uno de esos dos roles (lógica OR), igual que ocurriría con [Authorize(Roles=\"Admin,Manager\")]",["Exige que el usuario tenga ambos roles simultáneamente","Exige que el usuario no tenga ninguno de esos roles","Bloquea el acceso a cualquier usuario autenticado, sin importar su rol"],0,"RequireRole con varios roles como argumentos también se evalúa como OR: basta con que el usuario posea uno cualquiera de los roles indicados."),
   sqr("Si un frontend en https://miapp.com necesita llamar a este endpoint desde el navegador, ¿qué se necesita configurar además de la autenticación y autorización mostradas?","Una política CORS que incluya explícitamente https://miapp.com en WithOrigins, junto con app.UseCors() antes de la autorización en el pipeline",["Nada adicional, la autenticación JWT ya habilita CORS automáticamente","Deshabilitar HTTPS en el servidor para simplificar la configuración","Agregar el origen del frontend como un rol más en RequireRole"],0,"JWT Bearer resuelve la identidad del usuario, pero es un mecanismo completamente independiente de si el navegador permite que el JavaScript de ese origen lea la respuesta; eso lo controla CORS."),
   sqr("¿Protege la política CORS configurada para https://miapp.com a este endpoint de que alguien lo invoque directamente con curl usando un token robado?","No: CORS no tiene ningún efecto sobre clientes que no son navegadores; la única defensa real en ese escenario es que el atacante no consiga un token válido y que los tokens expiren pronto",["Sí, CORS bloquea automáticamente cualquier origen no listado, sin importar el tipo de cliente","Sí, siempre que el token JWT también esté cifrado","No, pero solo porque el endpoint usa POST en vez de GET"],0,"Reforzando el concepto del módulo: CORS es una restricción de navegador, no una barrera contra herramientas o scripts que llamen directamente a la API con un token válido."),
   sqr("¿Qué ocurre si builder.Configuration[\"Jwt:Key\"] es null (por ejemplo, porque el secreto nunca se configuró en ese ambiente)?","La línea Encoding.UTF8.GetBytes(...) lanzaría una excepción en tiempo de ejecución al intentar operar sobre un valor null, impidiendo que la aplicación arranque correctamente configurada",["La aplicación usa una clave por defecto generada aleatoriamente de forma transparente","El middleware de JWT Bearer se desactiva automáticamente sin errores","Todos los tokens se aceptan sin validar la firma en ese caso"],0,"Sin la clave configurada, no hay forma de validar firmas correctamente; el código mostrado fallaría explícitamente al iniciar en vez de degradar silenciosamente la seguridad."),
   sqr("¿ValidateLifetime = true en este ejemplo evita que un token robado siga siendo válido para siempre?","Solo limita la ventana de validez del token a su tiempo de expiración configurado; no revoca el token antes de esa fecha, por lo que sigue siendo válido durante toda su vida útil si es robado antes de expirar",["Sí, invalida inmediatamente cualquier token si se detecta un uso sospechoso","No tiene ningún efecto sobre la seguridad del token","Sí, hace que el token deje de funcionar apenas se usa una vez"],0,"ValidateLifetime solo hace cumplir la expiración ya definida en el token; para mitigar el robo de tokens de forma más agresiva se necesitan tokens de vida corta, refresh tokens y, si hace falta revocación temprana, un mecanismo adicional."),
   sqr("¿Es correcto decir que, una vez pasada la autenticación JWT, ya no hace falta ninguna otra verificación para este endpoint?","No: superar la autenticación (tener un token válido) es un paso previo distinto de superar la policy CanManageOrders; ambos deben cumplirse, cada uno resolviendo una pregunta distinta (quién eres vs. qué puedes hacer)",["Sí, un token JWT válido ya implica automáticamente tener todos los permisos necesarios","Sí, porque RequireAuthorization solo repite la misma comprobación que JWT Bearer","No, pero solo en endpoints que usan el verbo POST"],1,"El ejemplo aplica ambos pasos explícitamente (JWT Bearer para autenticación, RequireAuthorization(\"CanManageOrders\") para autorización), reflejando que son etapas independientes y ambas necesarias."),
   sqr("Resumiendo el diseño completo del endpoint, ¿qué combinación de decisiones refleja mejor las buenas prácticas de seguridad cubiertas en el módulo?","Clave de firma leída desde configuración externa (no hardcodeada), validación completa del JWT (issuer/audience/expiración/firma), autorización por policy en vez de lógica manual, y CORS limitado a orígenes explícitos conocidos",["Clave de firma como literal en el código, sin validar expiración, y CORS con AllowAnyOrigin() más credenciales habilitadas","Sin autenticación pero con un chequeo manual de un header personalizado que contiene el rol del usuario","Confiar en que HTTPS por sí solo hace innecesarias tanto la autenticación como la autorización"],0,"El diseño coherente combina secretos gestionados fuera del código, validación estricta y completa del token, autorización expresada declarativamente por policy, y una configuración de CORS que no debilita la protección de credenciales."),
  ]},
];
